function design(site, analyse) {
  const xs = [0, 4.03, 8.06, 12.09, 16.12, 20.15, 24.18, 28.21, 32.24, 36.27, 40.3];
  const sections = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
    "CHS60.3x4", "CHS76.1x3.2", "CHS76.1x4", "CHS88.9x4",
    "CHS88.9x5", "CHS114.3x4", "CHS114.3x5", "CHS139.7x5",
    "CHS139.7x6.3", "CHS168.3x5", "CHS168.3x6.3", "CHS193.7x6.3",
    "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];

  const note =
    "A 4.72 m deep, pinned AL7075 CHS box-Pratt truss uses triangulated side webs, top and bottom plan bracing, and transverse bracing; member sizes are analysis-searched with conservative margins.";

  const nodes = [];
  for (let i = 0; i <= 10; i++) {
    nodes.push({ id: "BL" + i, x: xs[i], y: -4.72, z: -2.65, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xs[i], y: -4.72, z:  2.65, joint: "pin" });
  }

  const edges = [];
  const keys = [];
  function add(a, b, group) {
    edges.push({ a, b, group });
    if (keys.indexOf(group) < 0) keys.push(group);
  }
  const mirror = (i, n) => Math.min(i, n - 1 - i);

  // Longitudinal chords.
  for (let i = 0; i < 10; i++) {
    add("L" + i, "L" + (i + 1), "TC");
    add("R" + i, "R" + (i + 1), "TC");
    add("BL" + i, "BL" + (i + 1), "BC");
    add("BR" + i, "BR" + (i + 1), "BC");
  }

  // Side-truss posts and Pratt diagonals.
  for (let i = 0; i <= 10; i++) {
    const g = "V" + mirror(i, 11);
    add("L" + i, "BL" + i, g);
    add("R" + i, "BR" + i, g);
  }
  for (let i = 0; i < 10; i++) {
    const g = "D" + mirror(i, 10);
    if (i < 5) {
      add("L" + i, "BL" + (i + 1), g);
      add("R" + i, "BR" + (i + 1), g);
    } else {
      add("L" + (i + 1), "BL" + i, g);
      add("R" + (i + 1), "BR" + i, g);
    }
  }

  // Transverse ties, longitudinal-plane triangulation, and cross-section bracing.
  for (let i = 0; i <= 10; i++) {
    add("L" + i, "R" + i, "XT");
    add("BL" + i, "BR" + i, "XB");
    add("L" + i, "BR" + i, "F");
  }
  for (let i = 0; i < 10; i++) {
    add("L" + i, "R" + (i + 1), "PT");
    add("BL" + i, "BR" + (i + 1), "PB");
  }

  const keyIndex = {};
  keys.forEach((k, i) => { keyIndex[k] = i; });
  const lastSection = sections.length - 1;

  function makeDesign(indices) {
    return {
      note,
      nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin" })),
      members: edges.map(e => ({
        a: e.a,
        b: e.b,
        spec: "AL7075 " + sections[indices[keyIndex[e.group]]]
      }))
    };
  }

  const maxCalls = 190;
  let calls = 0;
  const cache = new Map();

  function evaluate(indices) {
    const key = indices.join(",");
    if (cache.has(key)) return cache.get(key);
    if (calls >= maxCalls) return null;

    let result;
    try {
      result = analyse(makeDesign(indices));
    } catch (err) {
      result = { error: String(err) };
    }
    calls++;
    const record = { indices: indices.slice(), result };
    cache.set(key, record);
    return record;
  }

  function numeric(v) {
    return typeof v === "number" && isFinite(v);
  }

  function fatigueUtil(v) {
    if (numeric(v)) return v > 2 ? v / 23.58 : v;
    if (v && typeof v === "object") {
      if (numeric(v.util)) return v.util;
      if (numeric(v.ratio)) return v.ratio;
      if (numeric(v.maxUtil)) return v.maxUtil;
      if (numeric(v.range) && numeric(v.limit) && v.limit > 0) return v.range / v.limit;
      if (numeric(v.stressRange) && numeric(v.limit) && v.limit > 0) {
        return v.stressRange / v.limit;
      }
    }
    return null;
  }

  const tiers = [
    { util: 0.66, cr: 7.0, deflection: 0.84, frequency: 2.25, fatigue: 0.82 },
    { util: 0.74, cr: 6.2, deflection: 0.90, frequency: 2.10, fatigue: 0.90 },
    { util: 0.90, cr: 5.35, deflection: 0.98, frequency: 2.00, fatigue: 0.98 },
    { util: 0.99, cr: 5.00, deflection: 0.995, frequency: 2.00, fatigue: 0.995 }
  ];

  function acceptable(record, tier) {
    if (!record || !record.result) return false;
    const a = record.result;
    if (a.error || a.ok !== true) return false;
    if (a.robustness === false) return false;
    if (a.robustness && typeof a.robustness === "object" &&
        (a.robustness.ok === false || a.robustness.passed === false)) return false;

    if (numeric(a.maxUtil) && a.maxUtil > tier.util) return false;

    const cr = numeric(a.alpha_crMin) ? a.alpha_crMin : a.alpha_cr;
    if (numeric(cr) && cr < tier.cr) return false;

    if (numeric(a.sag) && numeric(a.sagLimit) && a.sagLimit > 0 &&
        a.sag / a.sagLimit > tier.deflection) return false;
    if (numeric(a.sway) && numeric(a.swayLimit) && a.swayLimit > 0 &&
        a.sway / a.swayLimit > tier.deflection) return false;

    if (numeric(a.frequency) && a.frequency < tier.frequency) return false;

    const fu = fatigueUtil(a.fatigueWorst);
    if (numeric(fu) && fu > tier.fatigue) return false;
    return true;
  }

  function massOf(record) {
    return record && record.result && numeric(record.result.mass)
      ? record.result.mass
      : Infinity;
  }

  const uniform = Array(keys.length).fill(Math.min(17, lastSection));
  const maximum = Array(keys.length).fill(lastSection);
  const customValues = {
    TC: 21, BC: 19,
    V0: 20, V1: 19, V2: 18, V3: 17, V4: 16, V5: 14,
    D0: 19, D1: 18, D2: 17, D3: 16, D4: 14,
    XT: 17, XB: 17, PT: 18, PB: 18, F: 18
  };
  const custom = keys.map(k =>
    Math.max(0, Math.min(lastSection,
      numeric(customValues[k]) ? customValues[k] : 17))
  );
  const seeds = [maximum, custom, uniform];

  let selected = null;

  function improve(start, tier) {
    let current = start;
    let currentMass = massOf(current);
    let best = current;

    for (let pass = 0; pass < 2 && calls < maxCalls; pass++) {
      let changed = false;
      for (let g = 0; g < keys.length && calls < maxCalls; g++) {
        let lo = 0;
        let hi = current.indices[g];

        while (lo < hi && calls < maxCalls) {
          const mid = Math.floor((lo + hi) / 2);
          const trial = current.indices.slice();
          trial[g] = mid;
          const r = evaluate(trial);
          if (acceptable(r, tier)) hi = mid;
          else lo = mid + 1;
        }

        if (lo < current.indices[g] && calls < maxCalls) {
          const trial = current.indices.slice();
          trial[g] = lo;
          const r = evaluate(trial);
          if (acceptable(r, tier)) {
            current = r;
            changed = true;
            const m = massOf(current);
            if (m < currentMass) currentMass = m;
            if (massOf(current) < massOf(best)) best = current;
          }
        }
      }
      if (!changed) break;
    }
    return best;
  }

  for (let t = 0; t < tiers.length && calls < maxCalls; t++) {
    const tier = tiers[t];
    const feasible = [];
    for (const seed of seeds) {
      if (calls >= maxCalls) break;
      const r = evaluate(seed);
      if (acceptable(r, tier)) feasible.push(r);
    }
    if (!feasible.length) continue;

    feasible.sort((a, b) => massOf(a) - massOf(b));
    selected = improve(feasible[0], tier);
    break;
  }

  if (!selected) {
    for (const r of cache.values()) {
      if (r.result && r.result.ok === true && massOf(r) < massOf(selected)) selected = r;
    }
  }
  if (!selected) selected = evaluate(maximum);
  if (!selected) selected = { indices: maximum };

  return makeDesign(selected.indices || maximum);
}

function design(site, analyse) {
  const xs = [0, 4.03, 8.06, 12.09, 16.12, 20.15, 24.18, 28.21, 32.24, 36.27, 40.3];
  const sections = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
    "CHS60.3x4", "CHS76.1x3.2", "CHS76.1x4", "CHS88.9x4",
    "CHS88.9x5", "CHS114.3x4", "CHS114.3x5", "CHS139.7x5",
    "CHS139.7x6.3", "CHS168.3x5", "CHS168.3x6.3", "CHS193.7x6.3",
    "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];

  const note =
    "A 4.85 m-deep pinned S690 CHS box-Pratt truss retains 3D bracing and sizes symmetric member groups for strength, fatigue, stability, and stiffness margins.";

  const nodes = [];
  for (let i = 0; i <= 10; i++) {
    nodes.push({ id: "BL" + i, x: xs[i], y: -4.85, z: -2.65, joint: "pin" });
    nodes.push({ id: "BR" + i, x: xs[i], y: -4.85, z:  2.65, joint: "pin" });
  }

  const edges = [];
  const groups = [];
  const groupIndex = Object.create(null);

  function add(a, b, group) {
    if (groupIndex[group] === undefined) {
      groupIndex[group] = groups.length;
      groups.push(group);
    }
    edges.push({ a, b, group });
  }

  const mirrorBay = i => Math.min(i, 9 - i);
  const mirrorStation = i => Math.min(i, 10 - i);

  // Longitudinal deck and lower chords, sized separately on each side.
  for (let i = 0; i < 10; i++) {
    const k = mirrorBay(i);
    for (const side of ["L", "R"]) {
      add(side + i, side + (i + 1), "TC_" + side + "_" + k);
      add("B" + side + i, "B" + side + (i + 1), "BC_" + side + "_" + k);
    }
  }

  // Side-truss posts and Pratt diagonals.
  for (let i = 0; i <= 10; i++) {
    const k = mirrorStation(i);
    add("L" + i, "BL" + i, "V_" + k);
    add("R" + i, "BR" + i, "V_" + k);
  }

  for (let i = 0; i < 10; i++) {
    const k = mirrorBay(i);
    if (i < 5) {
      add("L" + i, "BL" + (i + 1), "D_L_" + k);
      add("R" + i, "BR" + (i + 1), "D_R_" + k);
    } else {
      add("L" + (i + 1), "BL" + i, "D_L_" + k);
      add("R" + (i + 1), "BR" + i, "D_R_" + k);
    }
  }

  // Transverse frames and diagonal cross-section bracing.
  for (let i = 0; i <= 10; i++) {
    add("L" + i, "R" + i, "XT");
    add("BL" + i, "BR" + i, "XB");
    add("L" + i, "BR" + i, "F");
  }

  // Plan bracing restrains both the deck-level and lower compression chords.
  for (let i = 0; i < 10; i++) {
    add("L" + i, "R" + (i + 1), "PT");
    add("BL" + i, "BR" + (i + 1), "PB");
  }

  function makeDesign(indices) {
    return {
      note,
      nodes: nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin"
      })),
      members: edges.map(e => ({
        a: e.a,
        b: e.b,
        spec: "S690 " + sections[indices[groupIndex[e.group]]]
      }))
    };
  }

  const maxCalls = 390;
  let calls = 0;
  const cache = new Map();

  function numeric(v) {
    return typeof v === "number" && isFinite(v);
  }

  function evaluate(indices) {
    const key = indices.join(",");
    if (cache.has(key)) return cache.get(key);
    if (calls >= maxCalls) return null;

    let result;
    try {
      result = analyse(makeDesign(indices));
    } catch (err) {
      result = { error: String(err) };
    }
    calls++;

    const record = { indices: indices.slice(), result: result || {} };
    cache.set(key, record);
    return record;
  }

  function fatigueUtil(v) {
    if (numeric(v)) return v > 2 ? v / 66.31 : v;
    if (v && typeof v === "object") {
      if (numeric(v.util)) return v.util;
      if (numeric(v.ratio)) return v.ratio;
      if (numeric(v.maxUtil)) return v.maxUtil;

      const limit = numeric(v.limit) ? v.limit
        : numeric(v.allowable) ? v.allowable
        : numeric(v.allowed) ? v.allowed
        : null;
      const range = numeric(v.range) ? v.range
        : numeric(v.stressRange) ? v.stressRange
        : null;
      if (numeric(range) && numeric(limit) && limit > 0) return range / limit;
    }
    return null;
  }

  function acceptable(record, tier) {
    if (!record || !record.result) return false;
    const a = record.result;
    if (a.error || a.ok !== true) return false;

    if (a.robustness === false) return false;
    if (a.robustness && typeof a.robustness === "object" &&
        (a.robustness.ok === false || a.robustness.passed === false)) return false;

    if (numeric(a.maxUtil) && a.maxUtil > tier.util) return false;

    const cr = numeric(a.alpha_crMin) ? a.alpha_crMin : a.alpha_cr;
    if (numeric(cr) && cr < tier.cr) return false;

    if (numeric(a.sag) && numeric(a.sagLimit) && a.sagLimit > 0 &&
        a.sag / a.sagLimit > tier.deflection) return false;
    if (numeric(a.sway) && numeric(a.swayLimit) && a.swayLimit > 0 &&
        a.sway / a.swayLimit > tier.deflection) return false;

    if (numeric(a.frequency) && a.frequency < tier.frequency) return false;

    const fu = fatigueUtil(a.fatigueWorst);
    if (numeric(fu) && fu > tier.fatigue) return false;

    return true;
  }

  function massOf(record) {
    return record && record.result && numeric(record.result.mass)
      ? record.result.mass
      : Infinity;
  }

  const tiers = [
    { util: 0.62, cr: 7.0, deflection: 0.82, frequency: 2.15, fatigue: 0.78 },
    { util: 0.73, cr: 6.0, deflection: 0.92, frequency: 2.05, fatigue: 0.90 },
    { util: 0.90, cr: 5.2, deflection: 0.98, frequency: 2.01, fatigue: 0.98 }
  ];

  let current = null;
  let currentTier = null;
  let bestNominal = null;

  for (const tier of tiers) {
    for (const level of [21, 22, 23]) {
      const candidate = evaluate(Array(groups.length).fill(level));
      if (candidate && candidate.result && candidate.result.ok === true &&
          massOf(candidate) < massOf(bestNominal)) {
        bestNominal = candidate;
      }
      if (acceptable(candidate, tier)) {
        current = candidate;
        currentTier = tier;
        break;
      }
    }
    if (current) break;
  }

  if (!current) {
    current = bestNominal;
    currentTier = {
      util: Infinity, cr: -Infinity, deflection: Infinity,
      frequency: -Infinity, fatigue: Infinity
    };
  }

  if (!current) {
    const largest = Array(groups.length).fill(sections.length - 1);
    current = evaluate(largest) || { indices: largest };
  }

  if (current.result && currentTier) {
    for (let pass = 0; pass < 2 && calls < maxCalls; pass++) {
      let changed = false;
      let exhausted = false;

      for (let g = 0; g < groups.length; g++) {
        if (calls >= maxCalls) {
          exhausted = true;
          break;
        }

        const old = current.indices[g];
        if (old <= 0) continue;

        let lo = 0;
        let hi = old;
        let complete = true;

        while (lo < hi) {
          if (calls >= maxCalls) {
            complete = false;
            break;
          }

          const mid = Math.floor((lo + hi) / 2);
          const trial = current.indices.slice();
          trial[g] = mid;
          const result = evaluate(trial);

          if (acceptable(result, currentTier)) hi = mid;
          else lo = mid + 1;
        }

        if (!complete) {
          exhausted = true;
          break;
        }

        if (lo < old) {
          const trial = current.indices.slice();
          trial[g] = lo;
          const result = evaluate(trial);
          if (acceptable(result, currentTier)) {
            current = result;
            changed = true;
          }
        }
      }

      if (!changed || exhausted) break;
    }
  }

  return makeDesign(current.indices);
}

function design(site, analyse) {
  const xs = [0, 4.03, 8.06, 12.09, 16.12, 20.15, 24.18, 28.21, 32.24, 36.27, 40.3];

  const chsSections = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
    "CHS60.3x4", "CHS76.1x3.2", "CHS76.1x4", "CHS88.9x4",
    "CHS88.9x5", "CHS114.3x4", "CHS114.3x5", "CHS139.7x5",
    "CHS139.7x6.3", "CHS168.3x5", "CHS168.3x6.3", "CHS193.7x6.3",
    "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];
  const chsAreas = [
    2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67,
    13.18, 13.86, 17.17, 21.16, 26.4, 25.65, 32.06, 37.09,
    46.67, 53.06, 59.44, 82.62, 98.61, 134.74, 154.68, 221.67
  ];
  const wireSections = [
    "WIRE8", "WIRE10", "WIRE12", "WIRE16",
    "WIRE20", "WIRE24", "WIRE32", "WIRE40"
  ];
  const wireAreas = [0.3, 0.47, 0.68, 1.21, 1.88, 2.71, 4.83, 7.54];

  const variants = [
    { name: "steel-wire-box", core: "steel", plan: "wire", planX: true, frame: "wire", frameX: true },
    { name: "al-wire-box", core: "allAl", plan: "wire", planX: true, frame: "wire", frameX: true },
    { name: "side-al-wire-box", core: "sideAl", plan: "wire", planX: true, frame: "wire", frameX: true },
    { name: "steel-cable-plan", core: "steel", plan: "wire", planX: true, frame: "steel", frameX: false },
    { name: "al-steel-frame-cable-plan", core: "allAl", plan: "wire", planX: true, frame: "steel", frameX: false },
    { name: "side-al-steel-frame-cable-plan", core: "sideAl", plan: "wire", planX: true, frame: "steel", frameX: false },
    { name: "steel-cable-plan-frame-X", core: "steel", plan: "wire", planX: true, frame: "steel", frameX: true },
    { name: "side-al-steel-box", core: "sideAl", plan: "steel", planX: false, frame: "steel", frameX: false },
    { name: "steel-pratt-fallback", core: "steel", plan: "steel", planX: false, frame: "steel", frameX: false }
  ];

  const coordinates = Object.create(null);
  const nodeTemplate = [];
  for (let i = 0; i <= 10; i++) {
    coordinates["L" + i] = [xs[i], 0, -2.65];
    coordinates["R" + i] = [xs[i], 0, 2.65];
    coordinates["BL" + i] = [xs[i], -4.9, -2.65];
    coordinates["BR" + i] = [xs[i], -4.9, 2.65];

    nodeTemplate.push({ id: "BL" + i, x: xs[i], y: -4.9, z: -2.65, joint: "pin" });
    nodeTemplate.push({ id: "BR" + i, x: xs[i], y: -4.9, z: 2.65, joint: "pin" });
  }

  function coreMaterial(mode, key) {
    if (mode === "steel") return "S690";
    if (key === "TC_R_0") return "S690";
    if (mode === "allAl") return "AL7075";

    if (mode === "sideAl" &&
        (key.startsWith("TC_") || key.startsWith("BC_") ||
         key.startsWith("V_") || key.startsWith("D_"))) {
      return "AL7075";
    }
    return "S690";
  }

  function buildModel(topology) {
    const groups = [];
    const groupIndex = Object.create(null);
    const edges = [];

    function add(a, b, key, material) {
      let gi = groupIndex[key];
      if (gi === undefined) {
        gi = groups.length;
        groupIndex[key] = gi;
        groups.push({
          key,
          material,
          kind: material === "WIRE" ? "wire" : "chs",
          length: 0,
          count: 0
        });
      }

      const p = coordinates[a];
      const q = coordinates[b];
      groups[gi].length += Math.hypot(q[0] - p[0], q[1] - p[1], q[2] - p[2]);
      groups[gi].count++;
      edges.push({ a, b, g: gi });
    }

    const mirrorBay = i => Math.min(i, 9 - i);
    const mirrorStation = i => Math.min(i, 10 - i);

    // Longitudinal deck and lower chords.
    for (let i = 0; i < 10; i++) {
      const k = mirrorBay(i);
      for (const side of ["L", "R"]) {
        add(side + i, side + (i + 1), "TC_" + side + "_" + k,
            coreMaterial(topology.core, "TC_" + side + "_" + k));
        add("B" + side + i, "B" + side + (i + 1), "BC_" + side + "_" + k,
            coreMaterial(topology.core, "BC_" + side + "_" + k));
      }
    }

    // Side-truss posts and Pratt diagonals.
    for (let i = 0; i <= 10; i++) {
      const key = "V_" + mirrorStation(i);
      const mat = coreMaterial(topology.core, key);
      add("L" + i, "BL" + i, key, mat);
      add("R" + i, "BR" + i, key, mat);
    }

    for (let i = 0; i < 10; i++) {
      const k = mirrorBay(i);
      const leftKey = "D_L_" + k;
      const rightKey = "D_R_" + k;
      const leftMat = coreMaterial(topology.core, leftKey);
      const rightMat = coreMaterial(topology.core, rightKey);

      if (i < 5) {
        add("L" + i, "BL" + (i + 1), leftKey, leftMat);
        add("R" + i, "BR" + (i + 1), rightKey, rightMat);
      } else {
        add("L" + (i + 1), "BL" + i, leftKey, leftMat);
        add("R" + (i + 1), "BR" + i, rightKey, rightMat);
      }
    }

    // Transverse ties and bracing across the bridge.
    for (let i = 0; i <= 10; i++) {
      add("L" + i, "R" + i, "XT", coreMaterial(topology.core, "XT"));
      add("BL" + i, "BR" + i, "XB", coreMaterial(topology.core, "XB"));

      const frameMaterial = topology.frame === "wire" ? "WIRE" : "S690";
      add("L" + i, "BR" + i, "CF", frameMaterial);
      if (topology.frameX) {
        add("R" + i, "BL" + i, "CF", frameMaterial);
      }
    }

    // Plan bracing. Cable X-bracing avoids compression in the cables.
    for (let i = 0; i < 10; i++) {
      const planMaterial = topology.plan === "wire" ? "WIRE" : "S690";
      add("L" + i, "R" + (i + 1), "PT", planMaterial);
      add("BL" + i, "BR" + (i + 1), "PB", planMaterial);

      if (topology.planX) {
        add("R" + i, "L" + (i + 1), "PT", planMaterial);
        add("BR" + i, "BL" + (i + 1), "PB", planMaterial);
      }
    }

