      ? "an aluminium core with a steel end-chord fatigue group"
      : topology.core === "sideAl"
        ? "aluminium side trusses with steel diaphragms"
        : "S690 steel side trusses";
    const planNote = topology.plan === "wire"
      ? "crossed tension-only plan cables"
      : "steel plan bracing";
    const frameNote = topology.frame === "wire"
      ? "crossed tension-only transverse cables"
      : "steel transverse bracing";

    return {
      topology,
      nodes: nodeTemplate,
      groups,
      edges,
      note: "A 4.9 m-deep pinned box-Pratt uses " + coreNote + ", " +
            planNote + ", and " + frameNote +
            ", with sections reduced only while the analysis margins hold."
    };
  }

  const models = variants.map(buildModel);
  const tiers = [
    { util: 0.62, cr: 7.0, deflection: 0.82, frequency: 2.15, fatigue: 0.72 },
    { util: 0.70, cr: 6.0, deflection: 0.90, frequency: 2.05, fatigue: 0.82 },
    { util: 0.80, cr: 5.3, deflection: 0.97, frequency: 2.01, fatigue: 0.90 },
    { util: 0.96, cr: 5.0, deflection: 0.995, frequency: 2.00, fatigue: 0.98 }
  ];

  const MAX_CALLS = 395;
  let calls = 0;
  const cache = new Map();

  function numeric(v) {
    return typeof v === "number" && isFinite(v);
  }

  function makeDesign(model, indices) {
    return {
      note: model.note,
      nodes: model.nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin"
      })),
      members: model.edges.map(e => {
