      : numeric(a.alpha_cr) ? a.alpha_cr
      : null;
    if (numeric(cr) && cr < tier.cr) return false;

    if (numeric(a.sag) && numeric(a.sagLimit) && a.sagLimit > 0 &&
        Math.abs(a.sag) / a.sagLimit > tier.deflection) return false;
    if (numeric(a.sway) && numeric(a.swayLimit) && a.swayLimit > 0 &&
