  let fallback = null;

  for (const model of models) {
    for (const level of [21, 22, 23]) {
      if (calls >= MAX_CALLS) break;

      const indices = model.groups.map(g =>
        g.kind === "wire" ? wireSections.length - 1 : level
      );
      const record = evaluate(model, indices);
      if (!nominalPass(record)) continue;

      const rank = rankOf(record);
      const candidate = { model, indices, record, rank };

      if (!fallback || massOf(record) < massOf(fallback.record)) {
        fallback = candidate;
      }
      if (rank >= 0 &&
          (!selected ||
           rank < selected.rank ||
           (rank === selected.rank && massOf(record) < massOf(selected.record)))) {
        selected = candidate;
      }
    }
  }

  if (!selected) selected = fallback;

  if (!selected) {
    const model = models[models.length - 1];
    const indices = model.groups.map(g =>
      g.kind === "wire" ? wireSections.length - 1 : chsSections.length - 1
    );
    selected = {
      model,
      indices,
      record: evaluate(model, indices),
      rank: -1
    };
  }

  const model = selected.model;
  const tier = selected.rank >= 0 ? tiers[selected.rank] : null;
  let current = selected.record;

  function feasible(record) {
    return tier ? acceptable(record, tier) : nominalPass(record);
  }

  function optionAreas(group) {
    return group.kind === "wire" ? wireAreas : chsAreas;
  }

  function priorityOrder(indices) {
    const items = model.groups.map((group, i) => {
      const options = optionAreas(group);
      const index = indices[i];
      const deltaArea = index > 0 ? options[index] - options[index - 1] : 0;
      const density = group.material === "AL7075" ? 2810 : 7850;
      const saving = Math.max(0, deltaArea) * 1e-4 * density *
        (group.length + 0.7 * group.count);
      return { i, saving };
    });
    items.sort((a, b) => b.saving - a.saving);
    return items.map(item => item.i);
  }

  // First pass: use a discrete search to find the smallest acceptable option
  // for each repeated member group.
  const order = priorityOrder(current.indices);
  for (const g of order) {
    if (calls >= MAX_CALLS) break;

    const old = current.indices[g];
    if (old <= 0) continue;

    let lo = 0;
    let hi = old;
    let complete = true;

    while (lo < hi) {
      if (calls >= MAX_CALLS) {
        complete = false;
        break;
      }

      const mid = Math.floor((lo + hi) / 2);
      const trial = current.indices.slice();
      trial[g] = mid;
      const record = evaluate(model, trial);

      if (!record && calls >= MAX_CALLS) {
        complete = false;
        break;
      }
      if (feasible(record)) hi = mid;
      else lo = mid + 1;
    }

    if (!complete) break;

    if (lo < old && calls < MAX_CALLS) {
      const trial = current.indices.slice();
      trial[g] = lo;
      const record = evaluate(model, trial);
      if (feasible(record) && massOf(record) < massOf(current)) {
        current = record;
      }
    }
  }

  // Revisit groups after other members have become lighter.
  for (let pass = 0; pass < 5 && calls < MAX_CALLS; pass++) {
    let changed = false;
    const localOrder = priorityOrder(current.indices);

    for (const g of localOrder) {
      while (current.indices[g] > 0 && calls < MAX_CALLS) {
        const trial = current.indices.slice();
        trial[g]--;
        const record = evaluate(model, trial);

        if (feasible(record) && massOf(record) < massOf(current)) {
          current = record;
          changed = true;
        } else {
          break;
        }
      }
      if (calls >= MAX_CALLS) break;
    }

    if (!changed) break;
  }

  return makeDesign(model, current.indices);
}

