    ].map(([id, area]) => ({ id, area })).sort((a, b) => a.area - b.area)
  };

  const coordinates = Object.create(null);
  const nodeTemplate = [];
  for (let i = 0; i <= 10; i++) {
    coordinates["L" + i] = [xs[i], 0, -2.65];
    coordinates["R" + i] = [xs[i], 0, 2.65];
    coordinates["BL" + i] = [xs[i], -4.9, -2.65];
    coordinates["BR" + i] = [xs[i], -4.9, 2.65];
    nodeTemplate.push({ id: "BL" + i, x: xs[i], y: -4.9, z: -2.65, joint: "pin" });
    nodeTemplate.push({ id: "BR" + i, x: xs[i], y: -4.9, z: 2.65, joint: "pin" });
  }

  function buildModel(withTopPlan, useIPE) {
    const groups = [];
    const groupIndex = Object.create(null);
    const edges = [];

    function add(a, b, key, family) {
      let gi = groupIndex[key];
      if (gi === undefined) {
        gi = groups.length;
        groupIndex[key] = gi;
        groups.push({
          key,
          material: "S690",
          family: family || "CHS",
          options: catalogues[family || "CHS"],
          length: 0,
          count: 0
        });
      }
      const p = coordinates[a];
      const q = coordinates[b];
      groups[gi].length += Math.hypot(q[0] - p[0], q[1] - p[1], q[2] - p[2]);
      groups[gi].count++;
      edges.push({ a, b, g: gi });
    }

    const mirrorBay = i => Math.min(i, 9 - i);
    const mirrorStation = i => Math.min(i, 10 - i);

    // Deck and lower chords.
    for (let i = 0; i < 10; i++) {
      const k = mirrorBay(i);
      for (const side of ["L", "R"]) {
        add(side + i, side + (i + 1), "TC_" + side + "_" + k);
        add("B" + side + i, "B" + side + (i + 1), "BC_" + side + "_" + k);
      }
    }

    // Pratt posts and diagonals.
    for (let i = 0; i <= 10; i++) {
      const k = mirrorStation(i);
      add("L" + i, "BL" + i, "V_L_" + k);
      add("R" + i, "BR" + i, "V_R_" + k);
    }
    for (let i = 0; i < 10; i++) {
      const k = mirrorBay(i);
      if (i < 5) {
        add("L" + i, "BL" + (i + 1), "D_L_" + k);
        add("R" + i, "BR" + (i + 1), "D_R_" + k);
      } else {
        add("L" + (i + 1), "BL" + i, "D_L_" + k);
        add("R" + (i + 1), "BR" + i, "D_R_" + k);
      }
    }

    // Triangulated transverse frames.
    for (let i = 0; i <= 10; i++) {
      add("L" + i, "R" + i, "XT", useIPE ? "IPE" : "CHS");
      add("BL" + i, "BR" + i, "XB");
      add("L" + i, "BR" + i, "CF");
    }

    // Lower-plan bracing; deck-plane bracing is retained only when analysis
    // shows it is needed.
    for (let i = 0; i < 10; i++) {
      add("BL" + i, "BR" + (i + 1), "PB");
      if (withTopPlan) add("L" + i, "R" + (i + 1), "PT");
    }

    const idToGroup = Object.create(null);
    for (const e of edges) {
      idToGroup[e.a + "-" + e.b] = e.g;
      idToGroup[e.b + "-" + e.a] = e.g;
    }

    return {
      name: (withTopPlan ? "top-plan-" : "lower-plan-") + (useIPE ? "ipe" : "chs"),
      withTopPlan,
      useIPE,
      nodes: nodeTemplate,
      groups,
      edges,
      idToGroup
