  }

  const tiers = [
    { util: 0.76, cr: 6.0, deflection: 0.90, frequency: 2.08, fatigue: 0.84 },
    { util: 0.84, cr: 5.5, deflection: 0.96, frequency: 2.02, fatigue: 0.93 },
    { util: 0.98, cr: 5.0, deflection: 0.999, frequency: 2.00, fatigue: 0.99 }
  ];

  const MAX_CALLS = 395;
  let calls = 0;
  const cache = new Map();

  function numeric(v) {
    return typeof v === "number" && isFinite(v);
  }

  function makeDesign(model, indices, materials) {
    return {
      note: "Analysis-sized full-depth pinned box-Pratt bridge.",
      nodes: model.nodes.map(n => ({
        id: n.id, x: n.x, y: n.y, z: n.z, joint: "pin"
      })),
      members: model.edges.map(e => ({
        a: e.a,
        b: e.b,
        spec: materials[e.g] + " " + model.groups[e.g].options[indices[e.g]].id
      }))
    };
  }

  function evaluate(model, indices, materials) {
    const key = model.name + "|" + indices.join(",") + "|" + materials.join(",");
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAX_CALLS) return null;

    let result;
    try {
      result = analyse(makeDesign(model, indices, materials)) || {};
    } catch (err) {
      result = { error: String(err) };
    }
    calls++;

    const record = {
      model,
      indices: indices.slice(),
      materials: materials.slice(),
      result
    };
    cache.set(key, record);
    return record;
  }

  function robustnessOK(a) {
    if (a.robustness === false) return false;
    if (a.robustness && typeof a.robustness === "object" &&
        (a.robustness.ok === false || a.robustness.passed === false)) return false;
    return true;
  }

  function nominalPass(record) {
    return !!(record && record.result && !record.result.error &&
      record.result.ok === true && robustnessOK(record.result));
  }

  function fatigueUtil(v) {
    if (numeric(v)) return v > 2 ? v / 36.84 : v;
    if (v && typeof v === "object") {
      if (numeric(v.util)) return v.util;
      if (numeric(v.ratio)) return v.ratio;
      if (numeric(v.maxUtil)) return v.maxUtil;
      const limit = numeric(v.limit) ? v.limit
        : numeric(v.allowable) ? v.allowable
        : numeric(v.allowed) ? v.allowed : null;
      const range = numeric(v.range) ? v.range
        : numeric(v.stressRange) ? v.stressRange : null;
      if (numeric(range) && numeric(limit) && limit > 0) return range / limit;
      if (numeric(range)) return range / 36.84;
    }
    return null;
  }

  function acceptable(record, tier) {
    if (!nominalPass(record)) return false;
    const a = record.result;

    if (numeric(a.maxUtil) && a.maxUtil > tier.util) return false;

    const cr = numeric(a.alpha_crMin) ? a.alpha_crMin
      : numeric(a.alpha_cr) ? a.alpha_cr : null;
    if (numeric(cr) && cr < tier.cr) return false;

    if (numeric(a.sag) && numeric(a.sagLimit) && a.sagLimit > 0 &&
        Math.abs(a.sag) / a.sagLimit > tier.deflection) return false;
    if (numeric(a.sway) && numeric(a.swayLimit) && a.swayLimit > 0 &&
        Math.abs(a.sway) / a.swayLimit > tier.deflection) return false;

    const frequency = numeric(a.frequency) ? a.frequency
      : numeric(a.fMin) ? a.fMin : null;
    if (numeric(frequency) && frequency < tier.frequency) return false;

    const fu = fatigueUtil(a.fatigueWorst);
    if (numeric(fu) && fu > tier.fatigue) return false;

    return true;
  }

  function rankOf(record) {
    if (!nominalPass(record)) return 99;
    for (let i = 0; i < tiers.length; i++) {
      if (acceptable(record, tiers[i])) return i;
    }
    return tiers.length;
  }

  function massOf(record) {
    return record && record.result && numeric(record.result.mass)
      ? record.result.mass : Infinity;
  }

  function uniformIndices(model, level) {
    return model.groups.map(g => {
      const n = g.options.length;
      const index = g.family === "CHS"
        ? level
        : Math.round(level * (n - 1) / 23);
      return Math.max(0, Math.min(n - 1, index));
    });
  }

  const models = [
    buildModel(false, true),
    buildModel(false, false),
    buildModel(true, true),
    buildModel(true, false)
  ];

  let selected = null;
  const initialLevels = [18, 19, 20, 21, 22, 23];

  for (const model of models) {
    const materials = model.groups.map(g => g.material);
    for (const level of initialLevels) {
      if (calls >= MAX_CALLS) break;
      const indices = uniformIndices(model, level);
      const record = evaluate(model, indices, materials);
      const rank = rankOf(record);
      if (rank >= 99) continue;

      const candidate = { model, indices, materials, record, rank };
      if (!selected || candidate.rank < selected.rank ||
          (candidate.rank === selected.rank &&
           massOf(candidate.record) < massOf(selected.record))) {
        selected = candidate;
      }
    }
  }

  if (!selected) {
    const model = models[3];
    const indices = uniformIndices(model, 21);
    const materials = model.groups.map(g => g.material);
    const record = evaluate(model, indices, materials);
    selected = { model, indices, materials, record, rank: rankOf(record) };
  }

  const model = selected.model;
  let current = selected.record;
  const activeTier = selected.rank < tiers.length ? tiers[selected.rank] : null;

  function feasible(record) {
    return activeTier ? acceptable(record, activeTier) : nominalPass(record);
  }

  function priorityOrder(indices) {
    return model.groups.map((g, i) => {
      const options = g.options;
      const idx = indices[i];
      const delta = idx > 0 ? options[idx].area - options[idx - 1].area : 0;
      const saving = Math.max(0, delta) * 1e-4 * 7850 *
        (g.length + 0.7 * g.count);
      return { i, saving };
    }).sort((a, b) => b.saving - a.saving).map(x => x.i);
  }

  // Find the smallest feasible catalogue section for each repeated group.
  const baseStop = MAX_CALLS - 115;
  for (const g of priorityOrder(current.indices)) {
    if (calls >= baseStop) break;

    const old = current.indices[g];
    if (old <= 0) continue;

    let lo = 0;
    let hi = old;
    let best = current;
    let complete = true;

    while (lo < hi) {
      if (calls >= baseStop) {
        complete = false;
        break;
      }

      const mid = Math.floor((lo + hi) / 2);
      const trial = current.indices.slice();
      trial[g] = mid;
      const record = evaluate(model, trial, current.materials);

      if (!record && calls >= MAX_CALLS) {
        complete = false;
        break;
      }
      if (feasible(record)) {
        hi = mid;
        best = record;
      } else {
        lo = mid + 1;
      }
    }

    if (!complete) break;
    if (best.indices[g] < old && feasible(best) &&
        massOf(best) < massOf(current)) current = best;
  }

  function oneStepSweep(stop) {
    let changed = false;
    for (const g of priorityOrder(current.indices)) {
      if (calls >= stop) break;
      const old = current.indices[g];
      if (old <= 0) continue;

      const trial = current.indices.slice();
      trial[g] = old - 1;
      const record = evaluate(model, trial, current.materials);
      if (feasible(record) && massOf(record) < massOf(current)) {
        current = record;
        changed = true;
      }
    }
    return changed;
  }

  oneStepSweep(MAX_CALLS - 95);

  // Consider higher-fatigue steel only for groups identified as fatigue-critical.
  const fatigueScores = new Map();
  const listedMembers = current.result && Array.isArray(current.result.members)
    ? current.result.members : [];

  for (const m of listedMembers) {
    if (!/fatigue/i.test(String(m.mode || ""))) continue;
    let g = model.idToGroup[String(m.id || "")];
    if (g === undefined && m.a && m.b) g = model.idToGroup[m.a + "-" + m.b];
    if (g === undefined || current.materials[g] !== "S690") continue;
    const score = numeric(m.util) ? m.util : 1;
    fatigueScores.set(g, Math.max(fatigueScores.get(g) || 0, score));
  }

  if (fatigueScores.size === 0 && fatigueUtil(current.result.fatigueWorst) > 0.45) {
    const likely = model.groups.map((g, i) => ({ i, g }))
      .filter(x => /^(TC_|BC_|D_|PT|PB|XT|XB)/.test(x.g.key) &&
        current.materials[x.i] === "S690")
      .sort((a, b) =>
        b.g.options[current.indices[b.i]].area *
          (b.g.length + 0.7 * b.g.count) -
        a.g.options[current.indices[a.i]].area *
          (a.g.length + 0.7 * a.g.count));
    for (const x of likely.slice(0, 8)) fatigueScores.set(x.i, 0);
  }

  const fatigueCandidates = Array.from(fatigueScores.keys())
    .sort((a, b) => (fatigueScores.get(b) || 0) - (fatigueScores.get(a) || 0))
    .slice(0, 8);

  for (const g of fatigueCandidates) {
    if (calls >= MAX_CALLS - 40) break;
    if (current.materials[g] !== "S690") continue;

    const old = current.indices[g];
    const trialMaterials = current.materials.slice();
    trialMaterials[g] = "S460";

    let hi = -1;
    let best = null;
    const searchHigh = Math.min(model.groups[g].options.length - 1, old + 5);

    for (let idx = old; idx <= searchHigh; idx++) {
      if (calls >= MAX_CALLS - 40) break;
      const trial = current.indices.slice();
      trial[g] = idx;
      const record = evaluate(model, trial, trialMaterials);
      if (feasible(record)) {
        hi = idx;
        best = record;
        break;
      }
    }

    if (hi < 0 || !best) continue;

    let lo = 0;
    let complete = true;
    while (lo < hi) {
      if (calls >= MAX_CALLS - 40) {
        complete = false;
        break;
      }
      const mid = Math.floor((lo + hi) / 2);
      const trial = current.indices.slice();
      trial[g] = mid;
      const record = evaluate(model, trial, trialMaterials);
      if (feasible(record)) {
        hi = mid;
        best = record;
      } else {
        lo = mid + 1;
      }
    }

    if (complete && best && best.indices[g] < old &&
        massOf(best) < massOf(current)) current = best;
  }

  for (let pass = 0; pass < 2 && calls < MAX_CALLS; pass++) {
    if (!oneStepSweep(MAX_CALLS)) break;
  }

  const usesS460 = current.materials.some(m => m === "S460");
  const tieDescription = model.useIPE ? "IPE transverse ties" : "CHS transverse ties";
  const planDescription = model.withTopPlan
    ? "top- and lower-plane bracing"
    : "lower-plane bracing with triangulated cross-frames";
  const materialDescription = usesS460
    ? "selective S460 sizing for fatigue-critical groups"
    : "S690 throughout";
  const note = "A 4.9 m-deep pinned box-Pratt uses " + tieDescription +
    ", " + planDescription + ", and " + materialDescription + ".";

  const answer = makeDesign(model, current.indices, current.materials);
  answer.note = note;
  return answer;
}

function design(site, analyse) {
