      return { key: edgeKey(e), saving };
    }).sort((a, b) => b.saving - a.saving);

    for (const item of order) {
      if (calls >= stopAt) break;
      const index = current.edges.findIndex(e => edgeKey(e) === item.key);
      if (index < 0) continue;

      const e = current.edges[index];
      const list = listFor(e.mat);
      const info = e.mat === "WIRE" ? wireById.get(e.sec) : chsById.get(e.sec);
      if (!info || info.index <= 0) continue;

      const trial = current.edges.map((old, i) => i === index
        ? { ...old, sec: list[info.index - 1].id }
        : { ...old });
      const record = evaluate(trial);

