      const compression = Math.abs(m.compression);
      if (tension < 15 ||
          compression > Math.max(1, 0.015 * tension)) continue;

      list.push({
        key: edgeKey(e),
        priority: areaOf(e) * e.length
      });
    }

    return list.sort((a, b) => b.priority - a.priority);
  }

