  // the required single-rope-loss robustness case.
  const conversionStop = MAX_CALLS - 35;
  const wireStop = Math.min(conversionStop - 20, calls + 55);
  const wireOrder = tensionOnlyCandidates(current);

  for (const item of wireOrder) {
    if (calls >= wireStop) break;

    const index = current.edges.findIndex(e => edgeKey(e) === item.key);
    if (index < 0) continue;

    const e = current.edges[index];
    const m = metricMap(current).get(index);
    if (!m || e.mat !== "S690" ||
