    const requiredArea = Math.max(0.3, strengthArea, fatigueArea);

    let first = wires.findIndex(s => s.area >= requiredArea);
    if (first < 0) continue;

    for (let j = first; j <= Math.min(first + 2, wires.length - 1); j++) {
      if (calls >= wireStop) break;
      if (wires[j].area >= oldArea * 0.98) break;

      const trial = current.edges.map((old, k) => k === index
        ? { ...old, mat: "WIRE", sec: wires[j].id }
        : { ...old });
      const record = evaluate(trial);

      if (acceptable(record) && massOf(record) < massOf(current)) {
        current = record;
        break;
      }

      const rob = record && record.result && record.result.robustness;
      if (rob === false ||
          (rob && typeof rob === "object" &&
           (rob.ok === false || rob.passed === false))) break;
    }
  }

  // Aluminium is considered on remaining tension-only members, sized for
  // its lower fatigue allowance and checked by the same analysis engine.
  const aluminiumOrder = tensionOnlyCandidates(current);

  for (const item of aluminiumOrder) {
    if (calls >= conversionStop) break;

    const index = current.edges.findIndex(e => edgeKey(e) === item.key);
    if (index < 0) continue;

    const e = current.edges[index];
    const m = metricMap(current).get(index);
    if (!m || e.mat !== "S690" ||
        !numeric(m.tension) || !numeric(m.compression)) continue;

    const tension = Math.abs(m.tension);
    const oldArea = areaOf(e);
    const util = numeric(m.util) ? Math.max(0.05, Math.min(1.2, m.util)) : 0.5;

    const strengthArea =
      tension * 1.19 / (0.1 * 480 * 0.74) * 1.12;
    const fatigueArea =
      oldArea * util * 36.84 / (23.58 * 0.74) * 1.08;
    const requiredArea = Math.max(strengthArea, fatigueArea);
    const maximumLighterArea = oldArea * 7850 / 2810;

    let first = chs.findIndex(s => s.area >= requiredArea);
    if (first < 0) continue;

    for (let j = first; j <= Math.min(first + 2, chs.length - 1); j++) {
      if (calls >= conversionStop) break;
      if (chs[j].area >= maximumLighterArea) break;

      const trial = current.edges.map((old, k) => k === index
        ? { ...old, mat: "AL7075", sec: chs[j].id }
        : { ...old });
      const record = evaluate(trial);

      if (acceptable(record) && massOf(record) < massOf(current)) {
        current = record;
        break;
      }
    }
  }

  for (let pass = 0; pass < 4 && calls < MAX_CALLS - 1; pass++) {
    const changed = shrinkSweep(MAX_CALLS - 1);
    if (!changed) break;
  }

  return output(current.edges);
}

function design(site, analyse) {
  const xPos = [0,4.03,8.06,12.09,16.12,20.15,24.18,28.21,32.24,36.27,40.3];
  const sectionNames = [
    "CHS33.7x2.6","CHS42.4x3.2","CHS48.3x3.2","CHS60.3x3.2","CHS60.3x4",
    "CHS76.1x3.2","CHS76.1x4","CHS88.9x4","CHS88.9x5","CHS114.3x4",
    "CHS114.3x5","CHS139.7x5","CHS168.3x5","CHS139.7x6.3","CHS168.3x6.3",
    "CHS193.7x6.3","CHS193.7x8","CHS219.1x8","CHS244.5x8","CHS273x10",
    "CHS323.9x10","CHS355.6x12.5","CHS406.4x12.5","CHS457x16"
  ];
  const areas = [
    2.54,3.94,4.53,5.74,7.07,7.33,9.06,10.67,13.18,13.86,
    17.17,21.16,25.65,26.4,32.06,37.09,46.67,53.06,59.44,82.62,
    98.61,134.74,154.68,221.67
  ];
  const maxIdx = areas.length - 1;

  const memberDefs = [];
  const memberMats = [];
  function add(a, b, mat) {
    memberDefs.push({a, b});
    memberMats.push(mat);
  }

  for (let i = 0; i < 10; i++) {
    add(`L${i}`, `L${i+1}`, "S355");
    add(`R${i}`, `R${i+1}`, "S355");
    add(`B${i}`, `B${i+1}`, "S690");
  }
  for (let i = 0; i <= 10; i++) {
    add(`L${i}`, `R${i}`, "S355");
    add(`L${i}`, `B${i}`, "S355");
    add(`R${i}`, `B${i}`, "S355");
  }
  for (let i = 0; i < 10; i++) {
    if (i % 2 === 0) {
      add(`L${i}`, `R${i+1}`, "S355");
      add(`L${i}`, `B${i+1}`, "S355");
      add(`R${i}`, `B${i+1}`, "S355");
    } else {
      add(`R${i}`, `L${i+1}`, "S355");
      add(`L${i+1}`, `B${i}`, "S355");
      add(`R${i+1}`, `B${i}`, "S355");
    }
  }
  const N = memberDefs.length;

  function build(indices) {
    const nodes = [];
    for (let i = 0; i <= 10; i++) {
      nodes.push({id: `B${i}`, x: xPos[i], y: -4.9, z: 0, joint: "pin"});
    }
    const members = [];
    for (let k = 0; k < N; k++) {
      const a = memberDefs[k].a;
      const b = memberDefs[k].b;
      const spec = memberMats[k] + " " + sectionNames[indices[k]];
      members.push([a, b, spec]);
    }
    return {
      note: "Triangular pin-jointed space truss with central bottom chord",
      nodes,
      members
    };
  }

  function isGood(res) {
    if (!res || res.error || !res.ok) return false;
    if (res.maxUtil != null && res.maxUtil > 0.85) return false;
    if (res.alphaCr != null && res.alphaCr < 6.5) return false;
    if (res.sag != null && res.sagLimit != null && res.sag > 0.85 * res.sagLimit) return false;
    if (res.sway != null && res.swayLimit != null && res.sway > 0.85 * res.swayLimit) return false;
    if (res.frequency != null) {
      const fmin = res.fMin != null ? res.fMin : 2.0;
      if (res.frequency < 1.15 * fmin) return false;
    }
    if (res.fatigueWorst != null && res.fatigueWorst > 0.9) return false;
    return true;
  }

  let bestSafe = null, bestSafeMass = Infinity;
  let bestOk = null, bestOkMass = Infinity;
  let totalCalls = 0;

  function evaluateAndStore(idx) {
    if (totalCalls >= 400) return null;
    totalCalls++;
    let res;
    try {
      res = analyse(build(idx));
    } catch (e) {
      return {error: String(e)};
    }
    if (res && !res.error) {
      if (res.ok) {
        if (res.mass < bestOkMass) {
          bestOkMass = res.mass;
          bestOk = idx.slice();
        }
        if (isGood(res) && res.mass < bestSafeMass) {
          bestSafeMass = res.mass;
          bestSafe = idx.slice();
        }
      }
    }
    return res;
  }

  let indices = new Array(N).fill(14);
  for (let iter = 0; iter < 25; iter++) {
    const res = evaluateAndStore(indices);
    if (!res) break;
    if (res.error) {
      for (let i = 0; i < N; i++) indices[i] = Math.min(maxIdx, indices[i] + 2);
      continue;
    }
    let changed = false;
    if (res.members && res.members.length === N) {
      for (let i = 0; i < N; i++) {
        const u = res.members[i].util;
        if (u == null) continue;
        let idx = indices[i];
        if (u > 0.95) {
          if (idx < maxIdx) { indices[i] = idx + 1; changed = true; }
        } else if (u < 0.75) {
          if (idx > 0) { indices[i] = idx - 1; changed = true; }
          if (u < 0.4 && indices[i] > 1) {
            indices[i] = Math.max(0, indices[i] - 1);
          }
        }
      }
    } else {
      if (res.maxUtil > 0.9) {
        for (let i = 0; i < N; i++) indices[i] = Math.min(maxIdx, indices[i] + 1);
        changed = true;
      }
    }
    if (res.alphaCr != null && res.alphaCr < 7) {
      for (let i = 0; i < N; i++) indices[i] = Math.min(maxIdx, indices[i] + 1);
      changed = true;
    }
    if (res.frequency != null && res.fMin != null && res.frequency < 1.15 * res.fMin) {
      for (let i = 0; i < N; i++) indices[i] = Math.min(maxIdx, indices[i] + 1);
      changed = true;
    }
    if (res.sag != null && res.sagLimit != null && res.sag > 0.85 * res.sagLimit) {
      for (let i = 0; i < N; i++) indices[i] = Math.min(maxIdx, indices[i] + 1);
      changed = true;
    }
    if (res.sway != null && res.swayLimit != null && res.sway > 0.85 * res.swayLimit) {
      for (let i = 0; i < N; i++) indices[i] = Math.min(maxIdx, indices[i] + 1);
      changed = true;
    }
    if (res.failure && /mechanism/i.test(res.failure)) {
      for (let i = 0; i < N; i++) indices[i] = Math.min(maxIdx, indices[i] + 1);
      changed = true;
    }
    if (!changed) break;
  }

  if (!bestSafe) {
    let test = bestOk ? bestOk.slice() : new Array(N).fill(18);
    for (let k = 0; k < 10; k++) {
      const res = evaluateAndStore(test);
      if (res && res.ok && isGood(res)) {
        bestSafeMass = res.mass;
        bestSafe = test.slice();
        break;
      }
      for (let i = 0; i < N; i++) test[i] = Math.min(maxIdx, test[i] + 1);
    }
  }

  let current = bestSafe ? bestSafe.slice() : (bestOk ? bestOk.slice() : new Array(N).fill(20));
  let useSafe = !!bestSafe;

  for (let pass = 0; pass < 2; pass++) {
    let improved = false;
    const order = Array.from({length: N}, (_, i) => i)
      .sort((a, b) => areas[current[b]] - areas[current[a]]);
    for (const i of order) {
      if (current[i] === 0) continue;
      if (totalCalls >= 390) break;
      const old = current[i];
      current[i] = old - 1;
      const res = evaluateAndStore(current);
      if (res && res.ok && (useSafe ? isGood(res) : true)) {
        if (res.mass < bestSafeMass && isGood(res)) {
          bestSafeMass = res.mass;
          bestSafe = current.slice();
        }
        if (res.mass < bestOkMass) {
          bestOkMass = res.mass;
          bestOk = current.slice();
        }
        improved = true;
      } else {
        current[i] = old;
      }
    }
    if (!improved) break;
  }

  const finalIdx = bestSafe || bestOk || new Array(N).fill(20);
  return build(finalIdx);
}

function design(site, analyse) {
  const xPos = [0,4.03,8.06,12.09,16.12,20.15,24.18,28.21,32.24,36.27,40.3];

  function coord(id) {
    const side = id[0];
    const i = parseInt(id.slice(1), 10);
    const x = xPos[i];
    if (side === "L") return {x:x, y:0, z:-2.65};
    if (side === "R") return {x:x, y:0, z:2.65};
    return {x:x, y:-4.9, z:0};
  }

  const defs = [];
  function add(a, b) {
    const A = coord(a), B = coord(b);
    const dx = A.x-B.x, dy = A.y-B.y, dz = A.z-B.z;
    defs.push({a:a, b:b, L:Math.sqrt(dx*dx+dy*dy+dz*dz)});
  }

  for (let i=0; i<10; i++) {
    add(`L${i}`, `L${i+1}`);
    add(`R${i}`, `R${i+1}`);
    add(`B${i}`, `B${i+1}`);
  }
  for (let i=0; i<=10; i++) {
    add(`L${i}`, `R${i}`);
    add(`L${i}`, `B${i}`);
    add(`R${i}`, `B${i}`);
  }
  for (let i=0; i<10; i++) {
    if (i % 2 === 0) {
      add(`L${i}`, `R${i+1}`);
      add(`L${i}`, `B${i+1}`);
      add(`R${i}`, `B${i+1}`);
    } else {
      add(`R${i}`, `L${i+1}`);
      add(`L${i+1}`, `B${i}`);
      add(`R${i+1}`, `B${i}`);
    }
  }
  const N = defs.length;

  const chs = [
    ["33.7x2.6",2.54,3.1,34,2.6],
    ["42.4x3.2",3.94,7.6,42,3.2],
    ["48.3x3.2",4.53,11.6,48,3.2],
    ["60.3x3.2",5.74,23.5,60,3.2],
    ["60.3x4",7.07,28.2,60,4],
    ["76.1x3.2",7.33,48.8,76,3.2],
    ["76.1x4",9.06,59.1,76,4],
    ["88.9x4",10.67,96.3,89,4],
    ["88.9x5",13.18,116.4,89,5],
    ["114.3x4",13.86,211.1,114,4],
    ["114.3x5",17.17,256.9,114,5],
    ["139.7x5",21.16,480.5,140,5],
    ["139.7x6.3",26.4,588.6,140,6.3],
    ["168.3x5",25.65,855.8,168,5],
    ["168.3x6.3",32.06,1053.4,168,6.3],
    ["193.7x6.3",37.09,1630,194,6.3],
    ["193.7x8",46.67,2015.5,194,8],
    ["219.1x8",53.06,2959.6,219,8],
    ["244.5x8",59.44,4160.4,245,8],
    ["273x10",82.62,7154.1,273,10],
    ["323.9x10",98.61,12158.3,324,10],
    ["355.6x12.5",134.74,19852.2,356,12.5],
    ["406.4x12.5",154.68,30030.7,406,12.5],
    ["457x16",221.67,53959.4,457,16]
  ];
  const mats = [
    {name:"S355", fy:355},
    {name:"S460", fy:460},
    {name:"S690", fy:690}
  ];

  const candidates = [];
  for (const s of chs) {
    for (const m of mats) {
      candidates.push({
        id:s[0], mat:m.name, fy:m.fy, A:s[1], I:s[2], d:s[3], t:s[4],
        spec:m.name + " CHS" + s[0], cost:s[1]
      });
    }
  }
  candidates.sort((a,b) => (a.cost-b.cost) || (b.fy-a.fy));

  function findCandidate(spec) {
    const j = candidates.findIndex(c => c.spec === spec);
    return j >= 0 ? j : 0;
  }
  function findCostCandidate(desired) {
    for (let j=0; j<candidates.length; j++) {
      if (candidates[j].cost >= desired - 1e-9) return j;
    }
    return candidates.length-1;
  }
  function lowerCandidate(idx) {
    const cur = candidates[idx].cost;
    let best = -1;
    for (let j=0; j<candidates.length; j++) {
      if (candidates[j].cost < cur - 1e-9) {
        if (best < 0 ||
            candidates[j].cost > candidates[best].cost + 1e-9 ||
            (Math.abs(candidates[j].cost-candidates[best].cost) < 1e-9 &&
             candidates[j].fy > candidates[best].fy)) {
          best = j;
        }
      }
    }
    return best;
  }

  function capacity(c, L) {
    const tEff = Math.max(0.1, c.t - 0.2);
    const r = Math.min(1, tEff / c.t);
    const Aeff = c.A * 1e-4 * r;
    const Ieff = c.I * 1e-8 * r;
    const E = 210e9;
    const Ncr = Math.PI * Math.PI * E * Ieff / (L * L);
    const fy = c.fy * 1e6;
    const lam = Math.sqrt(Math.max(1e-12, Aeff * fy / Ncr));
    const alpha = 0.21;
    const phi = 0.5 * (1 + alpha * (lam - 0.2) + lam * lam);
    const disc = phi * phi - lam * lam;
    const chi = disc > 0 ? 1 / (phi + Math.sqrt(disc)) : 1;
    return {
      Nc: chi * Aeff * fy / 1.19,
      Nt: Aeff * fy / 1.19,
      W: c.I * 2e-5 / c.d
