      if (c.A < fatigueA - 1e-9) continue;
      const cv = capacity(c, L);
      const uT = Nt_kN * 1000 / cv.Nt;
      const uC = Nc_kN * 1000 / cv.Nc;
      const uN = Math.max(uT, uC);
      const uM = M_kNm > 0
        ? (M_kNm * 1000) / (cv.W * c.fy * 1e6 / 1.19)
        : 0;
      if (uN + uM <= target) return j;
    }
    return candidates.length - 1;
  }

  let totalCalls = 0;
  let bestSafe = null, bestSafeMass = Infinity, bestSafeRes = null;
  let bestOk = null, bestOkMass = Infinity, bestOkRes = null;

  function isSafe(res) {
    if (!res || res.error || !res.ok) return false;
    if (res.maxUtil != null && res.maxUtil > 0.82) return false;
    if (res.alphaCr != null && res.alphaCr < 6.0) return false;
    if (res.sag != null && res.sagLimit != null && res.sag > 0.85 * res.sagLimit) return false;
    if (res.sway != null && res.swayLimit != null && res.sway > 0.85 * res.swayLimit) return false;
    if (res.frequency != null) {
      const fmin = res.fMin != null ? res.fMin : 2;
      if (res.frequency < 1.15 * fmin) return false;
    }
    if (res.fatigueWorst != null && res.fatigueWorst > 0.88) return false;
    if (res.robustness === false) return false;
    if (res.robustness && res.robustness.ok === false) return false;
    return true;
  }

  function isGoodLoose(res) {
    if (!res || res.error || !res.ok) return false;
    if (res.maxUtil != null && res.maxUtil > 0.90) return false;
    if (res.alphaCr != null && res.alphaCr < 5.2) return false;
    if (res.sag != null && res.sagLimit != null && res.sag > 0.95 * res.sagLimit) return false;
    if (res.sway != null && res.swayLimit != null && res.sway > 0.95 * res.swayLimit) return false;
    if (res.frequency != null) {
      const fmin = res.fMin != null ? res.fMin : 2;
      if (res.frequency < 1.05 * fmin) return false;
    }
    if (res.fatigueWorst != null && res.fatigueWorst > 0.95) return false;
    return true;
  }

  function build(indices) {
    const nodes = [];
    for (let i=0; i<=10; i++) {
      nodes.push({id:`B${i}`, x:xPos[i], y:-4.9, z:0, joint:"pin"});
    }
    const members = [];
    for (let k=0; k<N; k++) {
      const c = candidates[indices[k]];
      members.push([defs[k].a, defs[k].b, c.spec]);
    }
    return {
      note:"Optimised S690/S460/S355 CHS triangular pin truss with central bottom chord",
      nodes:nodes,
      members:members
    };
  }

  function evalIdx(arr) {
    if (totalCalls >= 400) return null;
    totalCalls++;
    let res;
    try {
      res = analyse(build(arr));
    } catch (e) {
      return {error:String(e)};
    }
    if (res && !res.error) {
      if (res.ok && res.mass < bestOkMass) {
        bestOkMass = res.mass;
        bestOk = arr.slice();
        bestOkRes = res;
      }
      if (isSafe(res) && res.mass < bestSafeMass) {
        bestSafeMass = res.mass;
        bestSafe = arr.slice();
        bestSafeRes = res;
      }
    }
