  }

  const base = new Array(N).fill(findCandidate("S690 CHS273x10"));
  evalIdx(base);

  function vectorSize(startArr, target, maxIter) {
    let arr = startArr.slice();
    let res = evalIdx(arr);
    for (let it=0; it<maxIter && totalCalls<380; it++) {
      if (!res || res.error) {
        for (let i=0; i<N; i++) {
          arr[i] = Math.min(candidates.length-1, arr[i]+2);
        }
        res = evalIdx(arr);
        continue;
      }
      let newArr = arr.slice();
      let changed = false;
      for (let i=0; i<N; i++) {
        const m = res.members ? res.members[i] : null;
        if (!m) continue;
        const L = defs[i].L;
        const Nt = Math.abs(m.tension || 0);
        const Nc = Math.abs(m.compression || 0);
        const M = Math.abs(m.moment || 0);
        let fatigueA = 0;
        if (m.mode && /fatigue/i.test(m.mode)) {
          fatigueA = candidates[arr[i]].A * ((m.util || 0) / target);
        }
        let pred = chooseCandidate(L, Nt, Nc, M, fatigueA, target);
        if (m.util > target && candidates[pred].cost <= candidates[arr[i]].cost + 1e-6) {
          const needA = candidates[arr[i]].A * (m.util / target);
          const needIdx = findCostCandidate(needA);
          if (needIdx > pred) pred = needIdx;
        }
        if (pred !== arr[i]) {
          newArr[i] = pred;
          changed = true;
        }
      }
      let factor = 1;
      if (res.sag && res.sagLimit && res.sag > 0.85*res.sagLimit) {
        factor = Math.max(factor, res.sag/(0.85*res.sagLimit));
      }
      if (res.frequency && res.fMin && res.frequency < 1.15*res.fMin) {
        factor = Math.max(factor, Math.pow(1.15*res.fMin/res.frequency, 2));
      }
      if (res.alphaCr && res.alphaCr < 6) {
        factor = Math.max(factor, 6/res.alphaCr);
      }
      if (factor > 1.02) {
        for (let i=0; i<N; i++) {
          const desired = candidates[newArr[i]].cost * factor;
          const ni = findCostCandidate(desired);
          if (ni > newArr[i]) {
            newArr[i] = ni;
            changed = true;
          }
        }
      }
      arr = newArr;
      const r2 = evalIdx(arr);
      if (!r2) break;
      res = r2;
      if (!changed) break;
    }
    return {idx:arr, res:res};
  }

  function coordinate(startArr, startRes, passes, strict) {
    if (!startArr) return;
    let current = startArr.slice();
    let curRes = startRes || evalIdx(current);
    for (let pass=0; pass<passes && totalCalls<395; pass++) {
      let improved = false;
      const order = Array.from({length:N}, (_,i)=>i).sort((a,b) => {
        return candidates[current[b]].cost * defs[b].L -
               candidates[current[a]].cost * defs[a].L;
      });
      for (const i of order) {
        if (totalCalls >= 398) break;
        const oldIdx = current[i];
        const m = curRes && curRes.members ? curRes.members[i] : null;
        if (!m) continue;
        const L = defs[i].L;
        const Nt = Math.abs(m.tension || 0);
        const Nc = Math.abs(m.compression || 0);
        const M = Math.abs(m.moment || 0);
        const target = 0.78;
        let fatigueA = 0;
        if (m.mode && /fatigue/i.test(m.mode)) {
          fatigueA = candidates[oldIdx].A * ((m.util || 0) / target);
        }
        let pred = chooseCandidate(L, Nt, Nc, M, fatigueA, target);
        if (candidates[pred].cost >= candidates[oldIdx].cost - 1e-6) {
          if (m.util < 0.55) {
            const lo = lowerCandidate(oldIdx);
            if (lo >= 0) pred = lo;
          }
        }
        if (pred < 0 || candidates[pred].cost >= candidates[oldIdx].cost - 1e-6) continue;

        let trial = current.slice();
        trial[i] = pred;
        let r = evalIdx(trial);
        const good = strict ? isSafe(r) : (r && r.ok && isGoodLoose(r));
        if (good) {
