          const Nc2 = Math.abs(rm.compression || 0);
          const M2 = Math.abs(rm.moment || 0);
          const pred2 = chooseCandidate(L, Nt2, Nc2, M2, reqA, strict ? 0.82 : 0.85);
          if (candidates[pred2].cost < candidates[oldIdx].cost - 1e-6 && pred2 !== pred) {
            let trial2 = current.slice();
            trial2[i] = pred2;
            const r2 = evalIdx(trial2);
            const good2 = strict ? isSafe(r2) : (r2 && r2.ok && isGoodLoose(r2));
            if (good2) {
              current = trial2;
              curRes = r2;
              improved = true;
              continue;
            }
          }
        }

        const one = lowerCandidate(oldIdx);
        if (one >= 0 && one !== pred) {
          let trial3 = current.slice();
          trial3[i] = one;
          const r3 = evalIdx(trial3);
          const good3 = strict ? isSafe(r3) : (r3 && r3.ok && isGoodLoose(r3));
          if (good3) {
            current = trial3;
            curRes = r3;
            improved = true;
          }
        }
      }
      if (!improved) break;
    }
  }

  vectorSize(base, 0.72, 8);
  vectorSize(new Array(N).fill(0), 0.72, 8);

  if (bestOk && totalCalls < 370) {
    vectorSize(bestOk, 0.68, 4);
  }
  if (bestSafe) {
    coordinate(bestSafe, bestSafeRes, 2, true);
  }
  if (bestSafe && totalCalls < 380) {
    vectorSize(bestSafe, 0.70, 4);
    coordinate(bestSafe, bestSafeRes, 1, true);
  }

  let outArr = bestSafe ? bestSafe : (bestOk ? bestOk : base);
  return build(outArr);
}

