  function sizeAll(topo, arr, res, level) {
    if (!res || !res.members) return arr.slice();
    const out = arr.slice();
    for (let k = 0; k < topo.defs.length; k++) {
      const m = res.members[k];
      if (!m) continue;
      const L = topo.defs[k].L;
      const mode = m.mode || "";
      const lim = limitFor(mode, level);
      const target = lim * 0.94;
      out[k] = chooseCandidate(
        L,
        Math.abs(m.tension || 0),
        Math.abs(m.compression || 0),
        Math.abs(m.moment || 0),
        arr[k], m.util || 0, mode, target
      );
    }
    return out;
