  function fullyStress(topo, startArr, level, maxIter, callLimit) {
    let cur = startArr.slice();
    let res = evaluate(topo, cur);
    let best = null, bestRes = null, bestMass = Infinity;
    let prevMass = Infinity;
    for (let iter = 0; iter < maxIter && calls < callLimit; iter++) {
      if (!res || !res.ok) break;
      if (isAccept(res, level) && res.mass < bestMass) {
        best = cur.slice();
        bestRes = res;
        bestMass = res.mass;
      }
      const next = sizeAll(topo, cur, res, level);
      let changed = false;
      for (let k = 0; k < next.length; k++) {
        if (next[k] !== cur[k]) { changed = true; break; }
      }
      if (!changed) break;
      const nextRes = evaluate(topo, next);
      if (!nextRes || !nextRes.ok) break;
      cur = next;
      res = nextRes;
      if (isAccept(res, level) && res.mass < bestMass) {
        best = cur.slice();
        bestRes = res;
        bestMass = res.mass;
      }
      if (res.mass >= prevMass - 1e-6 && iter > 0) break;
      prevMass = res.mass;
    }
    return {best, bestRes, bestMass, last:cur, lastRes:res};
  }

  function repair(topo, cur, res, level, maxIter, callLimit) {
    for (let iter = 0; iter < maxIter && calls < callLimit; iter++) {
      if (!res || !res.ok) return {arr:cur, res};
      if (isAccept(res, level)) return {arr:cur, res};
      const next = cur.slice();
      let changed = false;
      for (let k = 0; k < topo.defs.length; k++) {
        const m = res.members && res.members[k];
        if (!m) continue;
        const lim = limitFor(m.mode, level);
        if ((m.util || 0) > lim) {
          const L = topo.defs[k].L;
          const j = chooseCandidate(
            L,
            Math.abs(m.tension || 0),
            Math.abs(m.compression || 0),
            Math.abs(m.moment || 0),
            cur[k], m.util || 0, m.mode || "", lim * 0.92
          );
          if (j !== cur[k]) {
            next[k] = j;
            changed = true;
          }
        }
      }
      if (!changed) return {arr:cur, res};
      cur = next;
      res = evaluate(topo, cur);
    }
    return {arr:cur, res};
