  function coordinate(topo, startArr, startRes, level, callLimit) {
    if (!startArr || !startRes || !isAccept(startRes, level)) {
      return null;
    }
    let cur = startArr.slice();
    let curRes = startRes;
    let best = cur.slice();
    let bestRes = curRes;
    let bestMass = curRes.mass;

    for (let pass = 0; pass < 4 && calls < callLimit; pass++) {
      let improved = false;
      const order = Array.from({length:topo.defs.length}, (_, i) => i)
        .sort((a,b) =>
          candidates[cur[b]].mass * topo.defs[b].L -
          candidates[cur[a]].mass * topo.defs[a].L
        );

      for (const k of order) {
        if (calls >= callLimit) break;
        if (!curRes || !curRes.ok) break;
        const m = curRes.members && curRes.members[k];
        if (!m) continue;

        const L = topo.defs[k].L;
        const mode = m.mode || "";
        const lim = limitFor(mode, level);
        const target = lim * 0.94;
        const Nt = Math.abs(m.tension || 0);
        const Nc = Math.abs(m.compression || 0);
        const M = Math.abs(m.moment || 0);
        const j0 = chooseCandidate(L, Nt, Nc, M, cur[k], m.util || 0, mode, target);
        const maxMass = candidates[cur[k]].mass;

        let trialCount = 0;
        for (let j = j0; j < candidates.length && trialCount < 3; j++) {
          if (candidates[j].mass >= maxMass - 1e-9) break;
          const trial = cur.slice();
          trial[k] = j;
          const r = evaluate(topo, trial);
          trialCount++;
