            cur = trial;
            curRes = r;
            improved = true;
            if (r.mass < bestMass) {
              best = trial.slice();
              bestRes = r;
              bestMass = r.mass;
            }
            break;
          }
        }
      }
      if (!improved) break;
    }
    return {best, bestRes, bestMass};
  }

  function optimizeTopology(topo, initArr, label, callLimit) {
    let res = evaluate(topo, initArr);
    if (!res || !res.ok) return null;

    const fs = fullyStress(topo, initArr, levelFinal, 5, callLimit);
    let best = null, bestRes = null, bestMass = Infinity;

    if (fs.best && isAccept(fs.bestRes, levelFinal)) {
      best = fs.best.slice();
      bestRes = fs.bestRes;
      bestMass = fs.bestMass;
    }

    const start = fs.last || initArr;
    const startRes = fs.lastRes || res;
    const rep = repair(topo, start, startRes, levelFinal, 5, callLimit);
    if (rep && rep.res && isAccept(rep.res, levelFinal)) {
      const c = coordinate(topo, rep.arr, rep.res, levelFinal, callLimit);
      if (c && c.best && c.bestMass < bestMass) {
