      };
    }
  }

  if (bestOverall && bestOverall.res && isAccept(bestOverall.res, levelFinal)) {
    return bestOverall.topo.build(bestOverall.arr);
  }

  // Last resort: exact attempt-3 seed.
  return topo3.build(seed3);
}

