  function capFor(c, L){
    let A = c.A * 1e-4;
    let Iy = c.Iy * 1e-8;
    let Iz = c.Iz * 1e-8;
    let W = Math.min(c.Wy||0, c.Wz||0) * 1e-6;
    let fy = c.fy * 1e6;
    let E = c.E * 1e6;
    if(c.corr > 0){
      const ratio = Math.max(0.1, Math.min(1, (c.t - c.corr)/c.t));
      A *= ratio;
      Iy *= ratio;
      Iz *= ratio;
      W *= ratio;
    }
    if(c.fam === "WIRE"){
      return {Nt:A*fy/1.19, Nc:0, M:0};
    }
    function NcFor(I){
      if(I <= 1e-14) return 0;
      const Ncr = Math.PI*Math.PI*E*I/(L*L);
      const lam = Math.sqrt(Math.max(1e-12, A*fy/Ncr));
      const alpha = 0.21;
      const phi = 0.5*(1 + alpha*(lam - 0.2) + lam*lam);
      const disc = phi*phi - lam*lam;
      const chi = disc > 0 ? 1/(phi + Math.sqrt(disc)) : 1;
      return chi*A*fy/1.19;
    }
    return {
      Nt:A*fy/1.19,
      Nc:Math.min(NcFor(Iy), NcFor(Iz)),
      M:W*fy/1.19
    };
  }

  function estimate(c, curC, m, L){
    if(c.fam === "WIRE" &&
       ((Math.abs(m.compression||0) > 0.1) || (Math.abs(m.moment||0) > 0.1))) return 10;
    const p = capFor(c, L);
    const Nt = Math.abs(m.tension||0) * 1000;
    const Nc = Math.abs(m.compression||0) * 1000;
    const M  = Math.abs(m.moment||0) * 1000;
    let u = 0;
    if(p.Nt > 0) u = Math.max(u, Nt/p.Nt);
    if(Nc > 0) u = Math.max(u, p.Nc > 0 ? Nc/p.Nc : 10);
    if(M > 0) u += p.M > 0 ? M/p.M : 10;
    if(/fatigue/i.test(m.mode||"")){
      let Acur = curC.A;
      let Anew = c.A;
      if(curC.corr > 0) Acur *= Math.max(0.1, Math.min(1, (curC.t-curC.corr)/curC.t));
      if(c.corr > 0) Anew *= Math.max(0.1, Math.min(1, (c.t-c.corr)/c.t));
      const uf = (m.util||0) * (Acur/Anew) * ((curC.fat||1)/(c.fat||1));
      if(uf > u) u = uf;
    }
    return u;
  }

  function acceptable(r, arr){
    if(!r || r.error || !r.ok) return false;
    if(r.alphaCr != null && r.alphaCr < 6.5) return false;
    if(r.sag != null && r.sagLimit != null && r.sag > 0.92*r.sagLimit) return false;
    if(r.sway != null && r.swayLimit != null && r.sway > 0.92*r.swayLimit) return false;
    if(r.frequency != null && r.frequency < 2.15) return false;
    if(r.fatigueWorst != null && r.fatigueWorst > 0.84) return false;
    if(r.robustness === false) return false;
    if(r.robustness && r.robustness.ok === false) return false;
    if(r.members){
      for(let i=0;i<r.members.length;i++){
        const m = r.members[i];
        if(!m) continue;
        let cap = 0.82;
        const c = candidates[arr[i]];
        if(c){
          if(c.name === "AL6082") cap = 0.80;
          if(c.fam === "WIRE") cap = 0.80;
        }
        if((m.util||0) > cap + 1e-9) return false;
      }
    }
    return true;
  }

  function optimize(topo, seed, startRes, callLimit){
    let cur = seed.slice();
    let res = startRes;
    if(!res || !res.ok || !acceptable(res, cur)) return null;
    let best = cur.slice();
    let bestRes = res;
    let bestMass = res.mass;

    for(let pass=0; pass<5 && calls<callLimit; pass++){
      let improved = false;
      const moves = [];
      for(let k=0;k<topo.defs.length;k++){
        if(!res.members || !res.members[k]) continue;
        const m = res.members[k];
        const curC = candidates[cur[k]];
        const opts = [];
        for(let j=0;j<candidates.length;j++){
          const c = candidates[j];
          if(c.mass >= curC.mass - 1e-9) continue;
          if(c.fam === "WIRE" &&
             !(topo.defs[k].a[0] === "B" && topo.defs[k].b[0] === "B")) continue;
          if(c.fam === "WIRE" && (Math.abs(m.compression||0) > 0.1)) continue;
          let cap = 0.81;
          if(c.name === "AL6082") cap = 0.79;
          if(c.fam === "WIRE") cap = 0.78;
          const u = estimate(c, curC, m, topo.defs[k].L);
          if(u <= cap) opts.push({j, u, mass:c.mass*topo.defs[k].L});
        }
        if(opts.length){
          opts.sort((a,b)=>a.mass-b.mass);
          const saving = curC.mass*topo.defs[k].L - opts[0].mass;
          if(saving > 1e-6) moves.push({k, saving, opts:opts.slice(0,4)});
        }
      }
      moves.sort((a,b)=>b.saving-a.saving);

      for(let mi=0; mi<moves.length && calls<callLimit; mi++){
        const k = moves[mi].k;
        if(!res.members || !res.members[k]) continue;
        const m = res.members[k];
        const curC = candidates[cur[k]];
        const opts = [];
        for(let j=0;j<candidates.length;j++){
          const c = candidates[j];
          if(c.mass >= curC.mass - 1e-9) continue;
          if(c.fam === "WIRE" &&
             !(topo.defs[k].a[0] === "B" && topo.defs[k].b[0] === "B")) continue;
          if(c.fam === "WIRE" && (Math.abs(m.compression||0) > 0.1)) continue;
          let cap = 0.81;
          if(c.name === "AL6082") cap = 0.79;
          if(c.fam === "WIRE") cap = 0.78;
          const u = estimate(c, curC, m, topo.defs[k].L);
          if(u <= cap) opts.push({j, u, mass:c.mass*topo.defs[k].L});
        }
        if(!opts.length) continue;
        opts.sort((a,b)=>a.mass-b.mass);
        let tried = 0;
        for(let oi=0; oi<opts.length && tried<3 && calls<callLimit; oi++){
          const j = opts[oi].j;
          if(j === cur[k]) continue;
          const trial = cur.slice();
          trial[k] = j;
          const r = evalC(topo, trial);
          tried++;
          if(r && r.ok && acceptable(r, trial) && r.mass < res.mass - 1e-6){
            cur = trial;
            res = r;
            improved = true;
            if(r.mass < bestMass){
              best = trial.slice();
              bestRes = r;
              bestMass = r.mass;
            }
            break;
          }
        }
      }
      if(!improved) break;
    }
    return {arr:best, res:bestRes, mass:bestMass};
  }

  const topo0 = {defs:defs0};
