  let bestRes = baseRes;
  let bestMass = (baseRes && baseRes.ok) ? baseRes.mass : Infinity;

  // Try the one-way diagonal truss first.
  if(calls < 360){
    const r1 = evalC(topo1, seedT1);
    if(r1 && r1.ok && acceptable(r1, seedT1)){
      const o1 = optimize(topo1, seedT1, r1, 310);
      if(o1 && o1.mass < bestMass){
        bestTopo = topo1;
        bestArr = o1.arr;
        bestRes = o1.res;
        bestMass = o1.mass;
      }
    } else if(calls < 330){
      const strongIdx = findSpec("S690 CHS355.6x12.5");
      const seedStrong = defs1.map(()=>strongIdx);
      const rs = evalC(topo1, seedStrong);
      if(rs && rs.ok && acceptable(rs, seedStrong)){
        const o1s = optimize(topo1, seedStrong, rs, 370);
        if(o1s && o1s.mass < bestMass){
          bestTopo = topo1;
          bestArr = o1s.arr;
          bestRes = o1s.res;
          bestMass = o1s.mass;
        }
      }
    }
  }

  // Then improve the known-good attempt-4 topology with residual budget.
  if(calls < 390){
    const o0 = optimize(topo0, baseIdx, baseRes, 390);
    if(o0 && o0.mass < bestMass){
      bestTopo = topo0;
      bestArr = o0.arr;
      bestRes = o0.res;
      bestMass = o0.mass;
    }
  }

  if(!bestRes || !bestRes.ok || !acceptable(bestRes, bestArr)){
    bestTopo = topo0;
    bestArr = baseIdx;
  }
  return build(bestTopo, bestArr);
}

