  function isAccept(r,caps) {
    if(!r || r.error || !r.ok) return false;
    if(r.alphaCr!=null && r.alphaCr < caps.alpha) return false;
    if(r.sag!=null && r.sagLimit!=null && r.sag > caps.sagFrac*r.sagLimit) return false;
    if(r.sway!=null && r.swayLimit!=null && r.sway > caps.swayFrac*r.swayLimit) return false;
    if(r.frequency!=null && r.frequency < caps.freq) return false;
    if(r.fatigueWorst!=null && r.fatigueWorst > caps.fatigueWorst) return false;
    if(r.robustness===false) return false;
    if(r.robustness && r.robustness.ok===false) return false;
    if(r.members){
      for(let i=0;i<r.members.length;i++){
        const m=r.members[i];
        if(!m) continue;
        if((m.util||0) > limitFor(m.mode,caps)+1e-9) return false;
      }
    }
    return true;
  }

  function effArea(c) {
    const ratio=Math.min(1,Math.max(0.1,(c.t-c.corr)/c.t));
    return c.A*1e-4*ratio;
  }

  function estimateUtil(c,L,Nt,Nc,M) {
    const ratio=Math.min(1,Math.max(0.1,(c.t-c.corr)/c.t));
    const A=c.A*1e-4*ratio;
    const I=c.I*1e-8*ratio;
    const fy=c.fy*1e6;
    const E=c.E*1e6;
    const Ncr=Math.PI*Math.PI*E*I/(L*L);
    const lam=Math.sqrt(Math.max(1e-12,A*fy/Ncr));
    const alpha=0.21;
    const phi=0.5*(1+alpha*(lam-0.2)+lam*lam);
    const disc=phi*phi-lam*lam;
    const chi=disc>0 ? 1/(phi+Math.sqrt(disc)) : 1;
    const NtRd=A*fy/1.19;
    const NcRd=chi*A*fy/1.19;
    const W=c.I*2e-5*ratio/c.d;
    const MRd=W*fy/1.19;
    return Math.max(Nt*1000/NtRd, Nc*1000/NcRd) + M*1000/MRd;
  }

  function chooseForMember(m, curIdx, L, caps) {
    const curC=candidates[curIdx];
    const Nt=Math.abs(m.tension||0);
    const Nc=Math.abs(m.compression||0);
    const M=Math.abs(m.moment||0);
    const mode=(m.mode||"").toLowerCase();
    const isFat=mode.indexOf("fatigue")>=0;
    const curEff=effArea(curC);
    const u0=m.util||0;

    let bestFeas=null, bestMass=Infinity;
    let bestFallback=null, bestScore=Infinity;

    for(let j=0;j<candidates.length;j++){
      const c=candidates[j];
      const uCap=estimateUtil(c,L,Nt,Nc,M);
      let uFat=0;
      if(isFat){
        const newEff=effArea(c);
        uFat = u0 * (curEff*curC.fat)/(newEff*c.fat);
      }
      const cap = mode.indexOf("buckling")>=0 ? caps.buck : caps.other;
      const score=Math.max(uCap/cap, uFat/caps.fat);
      if(score<=1.0001 && c.mass<bestMass){
        bestMass=c.mass; bestFeas=j;
      }
      if(score<bestScore){
        bestScore=score; bestFallback=j;
      }
    }
    return bestFeas!==null ? bestFeas : bestFallback;
  }

  function resizeLoop(topo, startArr, caps, maxIter) {
    let cur=startArr.slice();
    let res=evalT(topo,cur);
    let best=null,bestRes=null,bestMass=Infinity;
    if(res && isAccept(res,caps)){
      best=cur.slice(); bestRes=res; bestMass=res.mass;
    }
    for(let iter=0; iter<maxIter && calls<MAXCALL; iter++){
      if(!res || !res.members) break;
      let next=cur.slice();
      let changed=false;
      for(let k=0;k<topo.defs.length;k++){
        const m=res.members[k];
        if(!m) continue;
        const j=chooseForMember(m,cur[k],topo.defs[k].L,caps);
        if(j!==cur[k]){ next[k]=j; changed=true; }
      }
      if(!changed) break;
      const nextRes=evalT(topo,next);
      if(!nextRes || !nextRes.members) break;
      cur=next; res=nextRes;
      if(isAccept(res,caps) && res.mass<bestMass){
        best=cur.slice(); bestRes=res; bestMass=res.mass;
      }
    }
    if(best) return {arr:best,res:bestRes,mass:bestMass};
    return {arr:cur,res:res,mass:(res?res.mass:Infinity)};
  }

  function localDescent(topo, startArr, startRes, maxCalls) {
    if(!startRes || !isAccept(startRes,FINAL)) {
      return {arr:startArr,res:startRes,mass:Infinity};
    }
    const limit=Math.min(MAXCALL,calls+maxCalls);
    let cur=startArr.slice();
    let res=startRes;
    let best=cur.slice();
    let bestRes=res;
    let bestMass=res.mass;

    for(let pass=0; pass<4 && calls<limit; pass++){
      let improved=false;
      const order=Array.from({length:topo.defs.length},(_,i)=>i)
        .sort((a,b)=>candidates[cur[b]].mass*topo.defs[b].L - candidates[cur[a]].mass*topo.defs[a].L);

      for(const k of order){
        if(calls>=limit) break;
        if(!res || !res.members || !res.members[k]) continue;
        const m=res.members[k];
        const L=topo.defs[k].L;
        const curC=candidates[cur[k]];
        const Nt=Math.abs(m.tension||0);
        const Nc=Math.abs(m.compression||0);
        const M=Math.abs(m.moment||0);
        const mode=(m.mode||"").toLowerCase();
        const isFat=mode.indexOf("fatigue")>=0;
        const curEff=effArea(curC);
        const u0=m.util||0;

        const opts=[];
        for(let j=0;j<candidates.length;j++){
          const c=candidates[j];
          if(c.mass>=curC.mass-1e-9) continue;
          const uCap=estimateUtil(c,L,Nt,Nc,M);
          let uFat=0;
          if(isFat){
            const newEff=effArea(c);
            uFat=u0*(curEff*curC.fat)/(newEff*c.fat);
          }
          const cap=(mode.indexOf("buckling")>=0)?FINAL.buck:FINAL.other;
          if(uCap<=cap+1e-9 && uFat<=FINAL.fat+1e-9){
            opts.push({j,mass:c.mass*L});
          }
        }
        if(!opts.length) continue;
        opts.sort((a,b)=>a.mass-b.mass);

        let tried=0;
        for(let oi=0; oi<opts.length && tried<3 && calls<limit; oi++){
          const j=opts[oi].j;
          if(j===cur[k]) continue;
          const trial=cur.slice();
          trial[k]=j;
          const r=evalT(topo,trial);
          tried++;
          if(r && isAccept(r,FINAL) && r.mass<res.mass-1e-6){
            cur=trial; res=r; improved=true;
            if(r.mass<bestMass){
              best=trial.slice(); bestRes=r; bestMass=r.mass;
            }
            break;
          }
        }
      }
      if(!improved) break;
    }
    return {arr:best,res:bestRes,mass:bestMass};
  }

  // attempt-4 exact seed
  const baseSpecs = [
    "S690 CHS219.1x8","S690 SHS200x10","AL7075 SHS40x3",
    "S690 CHS219.1x8","S690 CHS168.3x5","S690 CHS193.7x8",
    "S690 CHS193.7x6.3","AL7075 CHS323.9x10","S690 CHS193.7x8",
    "S690 CHS193.7x6.3","S690 SHS150x8","S690 CHS244.5x8",
    "S690 SHS180x8","S690 CHS193.7x8","S690 CHS244.5x8",
    "S690 SHS180x8","S690 CHS219.1x8","S690 CHS244.5x8",
    "AL7075 CHS355.6x12.5","S690 CHS273x10","S690 CHS244.5x8",
    "S690 CHS219.1x8","S690 CHS219.1x8","S690 CHS193.7x8",
    "S690 CHS168.3x5","S690 SHS150x8","S690 CHS193.7x8",
    "S690 CHS168.3x5","AL7075 CHS193.7x6.3","AL7075 CHS42.4x3.2",
    "AL7075 CHS193.7x6.3","AL7075 SHS50x3","AL7075 CHS76.1x3.2",
    "AL7075 SHS60x4","S690 CHS139.7x5","S690 CHS139.7x5",
    "AL7075 SHS100x5","S690 CHS42.4x3.2","S690 CHS60.3x3.2",
    "S690 SHS60x4","S690 CHS139.7x5","S690 CHS139.7x5",
    "S690 CHS48.3x3.2","S690 CHS42.4x3.2","S690 CHS60.3x3.2",
    "S690 SHS60x4","S690 CHS139.7x5","S690 CHS139.7x5",
    "S690 CHS48.3x3.2","S690 CHS42.4x3.2","S690 CHS60.3x3.2",
    "AL7075 CHS168.3x5","S690 CHS139.7x5","S690 CHS139.7x5",
    "AL7075 SHS100x5","S690 CHS42.4x3.2","S690 CHS60.3x3.2",
    "AL7075 SHS60x4","AL7075 CHS168.3x5","S690 SHS100x5",
    "AL7075 SHS150x8","AL7075 SHS50x3","AL7075 CHS76.1x3.2",
    "S690 SHS180x8","S690 SHS100x8","AL7075 SHS150x8",
    "S690 CHS193.7x8","S690 CHS193.7x8","S690 CHS193.7x8",
    "S690 CHS193.7x8","S690 SHS100x5","AL7075 CHS193.7x8",
    "S690 CHS139.7x6.3","S690 CHS168.3x5","S690 CHS168.3x5",
    "AL7075 CHS193.7x8","S690 CHS168.3x5","S690 CHS88.9x5",
    "S690 CHS114.3x5","S690 CHS168.3x5","S690 CHS88.9x5",
    "S690 CHS76.1x3.2","S690 CHS168.3x6.3","S690 CHS168.3x5",
    "S690 CHS139.7x5","S690 CHS139.7x5","S690 CHS88.9x5",
    "S690 CHS168.3x5","S690 CHS193.7x8","S690 CHS193.7x8",
    "S690 CHS168.3x6.3","AL7075 SHS200x10","S690 SHS80x5"
  ];
  const baseIdx=baseSpecs.map(findSpec);

  const T0=makeTopo("alt","alt");
  const baseKeyMap=new Map();
  T0.defs.forEach((d,i)=>{
    baseKeyMap.set(d.a+"|"+d.b, baseSpecs[i]);
    baseKeyMap.set(d.b+"|"+d.a, baseSpecs[i]);
  });

  const strongIdx=findSpec("S690 CHS193.7x8");
  const lightIdx=findSpec("S690 CHS60.3x3.2");

  function mapSeed(topo) {
    return topo.defs.map(d=>{
      const spec=baseKeyMap.get(d.a+"|"+d.b);
      return spec ? findSpec(spec) : strongIdx;
    });
  }
  function uniformSeed(topo, idx) {
    return topo.defs.map(()=>idx);
  }

  // initial known-good fallback
  let bestOverall=null;
  {
    const r=evalT(T0,baseIdx);
    bestOverall={
      topo:T0,
      arr:baseIdx.slice(),
      res:r,
      mass:(r&&r.mass)?r.mass:11872,
      label:"attempt-4 fallback"
    };
  }

  function trySeed(topo, seedArr, maxLocal, label) {
    if(calls>=MAXCALL) return;
    const o=resizeLoop(topo,seedArr,FINAL,10);
    if(o && o.res && o.res.ok && isAccept(o.res,FINAL)){
      if(o.mass<bestOverall.mass){
        bestOverall={topo,arr:o.arr.slice(),res:o.res,mass:o.mass,label};
      }
      if(maxLocal>0 && calls<MAXCALL){
        const d=localDescent(topo,o.arr,o.res,maxLocal);
        if(d && d.res && isAccept(d.res,FINAL) && d.mass<bestOverall.mass){
          bestOverall={topo,arr:d.arr.slice(),res:d.res,mass:d.mass,label:label+"-local"};
        }
      }
    }
  }

  // Pratt-type side diagonals: make gravity diagonals predominantly tension.
  const T1=makeTopo("pratt","alt");
  trySeed(T1, mapSeed(T1), 55, "pratt-alt");
  trySeed(T1, uniformSeed(T1, lightIdx), 0, "pratt-alt-light");

  const T2=makeTopo("pratt","mirror");
  trySeed(T2, mapSeed(T2), 55, "pratt-mirrorR");
  trySeed(T2, uniformSeed(T2, lightIdx), 0, "pratt-mirrorR-light");

  const T3=makeTopo("alt","mirror");
  trySeed(T3, mapSeed(T3), 40, "alt-mirrorR");

  const T4=makeTopo("oneway","mirror");
  trySeed(T4, mapSeed(T4), 40, "oneway-mirrorR");

  const T5=makeTopo("pratt","mirrorL");
  trySeed(T5, mapSeed(T5), 35, "pratt-mirrorL");

  // final extra local search on current best if budget remains
  if(bestOverall && bestOverall.res && isAccept(bestOverall.res,FINAL) && calls<MAXCALL){
    const d=localDescent(bestOverall.topo,bestOverall.arr,bestOverall.res,MAXCALL-calls);
    if(d && d.res && isAccept(d.res,FINAL) && d.mass<bestOverall.mass){
      bestOverall={topo:bestOverall.topo,arr:d.arr,res:d.res,mass:d.mass,label:bestOverall.label+"-final"};
    }
  }

  return buildDesign(bestOverall.topo,bestOverall.arr,
    "Improved triangular space truss: Pratt/mirrored side diagonals to reduce compression buckling and fatigue in the webs");
}

