  for(let i=0;i<N;i++){const r=find(i);if(!groupMap.has(r))groupMap.set(r,[]);groupMap.get(r).push(i);}
  const groups=[...groupMap.values()];

  // Seed symmetrised from attempt-6: use heaviest base section in each symmetric group.
  const seedArr=new Array(N);
  for(const g of groups){
    let bi=baseIdx[g[0]],bm=cands[bi].mass;
    for(const k of g){const j=baseIdx[k];if(cands[j].mass>bm+1e-9){bm=cands[j].mass;bi=j;}}
    for(const k of g)seedArr[k]=bi;
  }

  let calls=0;const MAXCALL=385;const cache=new Map();
  function buildDesign(arr){
    return {
      note:"Robust symmetric search from attempt-6 with ROD/CHS/SHS resizing; hidden-load margins enforced.",
      nodes:bnodes.map(o=>({...o})),
      members:topo.map((d,i)=>[d.a,d.b,cands[arr[i]].spec])
    };
  }
  function evalArr(arr){
    const key=arr.join(",");
    if(cache.has(key))return cache.get(key);
    if(calls>=MAXCALL)return null;
    calls++;
    let r=null;
    try{r=analyse(buildDesign(arr));}catch(e){r={error:String(e)};}
    cache.set(key,r);return r;
  }

  function effArea(c){
    let A=c.A*1e-4;
    if(c.corr>0){
      const ratio=Math.max(0.1,Math.min(1,(c.t-c.corr)/c.t));
      A*=ratio;
    }
    return A;
  }
  function capacity(c,L){
    let A=c.A*1e-4,I=c.I*1e-8,W=c.Wy*1e-6;
    if(c.corr>0){
      const ratio=Math.max(0.1,Math.min(1,(c.t-c.corr)/c.t));
      A*=ratio;I*=ratio;W*=ratio;
    }
    const fy=c.fy*1e6,E=c.E*1e6;
    if(c.fam==="WIRE")return{Nt:A*fy/1.19,Nc:0,M:0};
    const al=(c.fam==="ROD"?0.49:0.21);
    let Nc=0;
    if(I>1e-16){
      const Ncr=Math.PI*Math.PI*E*I/(L*L);
      const lam=Math.sqrt(Math.max(1e-12,A*fy/Ncr));
      const phi=0.5*(1+al*(lam-0.2)+lam*lam);
      const disc=phi*phi-lam*lam;
      const chi=disc>0?1/(phi+Math.sqrt(disc)):1;
      Nc=chi*A*fy/1.19;
    }
    return{Nt:A*fy/1.19,Nc,M:W*fy/1.19};
