  const CAPS={buck:0.74,other:0.80,fat:0.78,alpha:9,sagFrac:0.90,swayFrac:0.90,freq:2.25,fatigueWorst:0.78};
  const TOP_STR=0.66,TOP_FAT=0.72;

  function candidateSatisfies(j,curJ,m,L,isTop){
    if(!m)return false;
    const c=cands[j];
    if(c.fam==="WIRE"&&((m.compression||0)>0.1||(m.moment||0)>0.1))return false;
    const p=capacity(c,L);
    const Nt=(m.tension||0)*1000,Nc=(m.compression||0)*1000,M=(m.moment||0)*1000;
    let u=0;
    if(Nt>0){if(p.Nt<=0)return false;u+=Nt/p.Nt;}
    if(Nc>0){if(p.Nc<=0)return false;u+=Nc/p.Nc;}
    if(M>0){if(p.M<=0)return false;u+=M/p.M;}
    const mode=(m.mode||"").toLowerCase();
    let cap=(mode.indexOf("buckling")>=0?CAPS.buck:(mode.indexOf("fatigue")>=0?CAPS.fat:CAPS.other));
    if(isTop)cap=Math.min(cap,(mode.indexOf("fatigue")>=0?TOP_FAT:TOP_STR));
    if(u>cap+1e-6)return false;

    let maxFat=0;
    const curC=cands[curJ];
    if(mode.indexOf("fatigue")>=0||c.fat<curC.fat){
      const Ac=effArea(curC),An=effArea(c);
      if(An<=0)return false;
      maxFat=(m.util||0)*(Ac/An)*((curC.fat||1)/(c.fat||1));
    }
    let fcap=(isTop?Math.min(CAPS.fat,TOP_FAT):CAPS.fat);
    if(maxFat>fcap+1e-6)return false;
    return true;
  }

  function utilRatio(j,curJ,m,L,isTop){
    if(!m)return 1e9;
    const c=cands[j],p=capacity(c,L);
    const Nt=(m.tension||0)*1000,Nc=(m.compression||0)*1000,M=(m.moment||0)*1000;
    let u=0;
    if(Nt>0)u+=p.Nt>0?Nt/p.Nt:1e6;
    if(Nc>0)u+=p.Nc>0?Nc/p.Nc:1e6;
    if(M>0)u+=p.M>0?M/p.M:1e6;
    const mode=(m.mode||"").toLowerCase();
    let cap=(mode.indexOf("buckling")>=0?CAPS.buck:(mode.indexOf("fatigue")>=0?CAPS.fat:CAPS.other));
    if(isTop)cap=Math.min(cap,(mode.indexOf("fatigue")>=0?TOP_FAT:TOP_STR));
    u/=cap;
    let f=0;
    const curC=cands[curJ];
    if(mode.indexOf("fatigue")>=0||c.fat<curC.fat){
      const Ac=effArea(curC),An=effArea(c);
      if(An<=0)f=1e6;
      else f=(m.util||0)*(Ac/An)*((curC.fat||1)/(c.fat||1));
    }
    let fcap=(isTop?Math.min(CAPS.fat,TOP_FAT):CAPS.fat);
    return Math.max(u,f/fcap);
  }

  function okReport(r,arr){
    if(!r||r.error||!r.ok)return false;
    if(r.alphaCr!=null&&r.alphaCr<CAPS.alpha)return false;
    if(r.sag!=null&&r.sagLimit!=null&&r.sag>CAPS.sagFrac*r.sagLimit)return false;
    if(r.sway!=null&&r.swayLimit!=null&&r.sway>CAPS.swayFrac*r.swayLimit)return false;
    if(r.frequency!=null&&r.frequency<CAPS.freq)return false;
    if(r.fatigueWorst!=null&&r.fatigueWorst>CAPS.fatigueWorst)return false;
    if(r.robustness===false)return false;
    if(r.robustness&&r.robustness.ok===false)return false;
    if(r.members){
      for(let i=0;i<r.members.length;i++){
        const m=r.members[i];if(!m)continue;
