  }

  function shrinkLoop(startArr){
    let cur=startArr.slice(),curR=evalArr(cur);
    let best=null;
    if(curR&&curR.ok&&okReport(curR,cur))best={arr:cur.slice(),r:curR,mass:curR.mass};
    for(let iter=0;iter<12&&calls<MAXCALL;iter++){
      if(!curR||!curR.members)break;
      const next=chooseMinimalAll(cur,curR);
