        for(let oi=0;oi<Math.min(opts.length,2)&&calls<MAXCALL;oi++){
          const j=opts[oi].j;
          const trial=cur.slice();
          for(const k of g)trial[k]=j;
          const tr=evalArr(trial);
          if(tr&&tr.ok&&okReport(tr,trial)&&tr.mass<curMass-1e-6){
            cur=trial;curR=tr;curMass=tr.mass;improved=true;
            if(tr.mass<best.mass)best={arr:trial.slice(),r:tr,mass:tr.mass};
