  const outArr=best?best.arr:baseIdx;
  const out=buildDesign(outArr);
  out.note=best?"Robust symmetric optimised triangular truss; attempt-6 topology with safety margins and steel ROD allowed.":
              "Fallback attempt-6 design (program did not find a safer lighter candidate).";
  return out;
}

