  function effProps(c) {
    let A = c.A * 1e-4, I = c.I * 1e-8;
    if (c.corr > 0) {
      const ratio = Math.max(0.1, Math.min(1, (c.t - c.corr) / c.t));
      A *= ratio; I *= ratio;
    }
    return {A,I};
  }
  function capSec(c,L) {
    const {A,I} = effProps(c);
    const W = I * 2000 / c.d;
    const fy = c.fy * 1e6, E = c.E * 1e6;
    const Nt = A * fy / 1.19;
    let Nc = 0;
    const Ncr = Math.PI * Math.PI * E * I / (L*L);
    if (Ncr > 0) {
      const lam = Math.sqrt(Math.max(1e-12, A * fy / Ncr));
      const alpha = 0.21;
      const phi = 0.5 * (1 + alpha*(lam-0.2) + lam*lam);
      const disc = Math.max(0, phi*phi - lam*lam);
      const chi = 1 / (phi + Math.sqrt(disc));
      Nc = chi * A * fy / 1.19;
    }
    const M = W * fy / 1.19;
    return {Nt,Nc,M,A,I,W};
  }
  function estimate(j, curJ, m, L) {
    const c = cands[j];
    const capc = capSec(c,L);
    const Nt = Math.abs(m.tension || 0);
    const Nc = Math.abs(m.compression || 0);
    const M  = Math.abs(m.moment || 0);
    const uT = Nt * 1000 / capc.Nt;
    const uC = Nc * 1000 / capc.Nc;
    const uM = M  * 1000 / capc.M;
    const uStatic = uT + uC + uM;
    const curC = cands[curJ];
    const Ac = effProps(curC).A, An = effProps(c).A;
    let uFat = 1e9;
    if (An > 0 && c.fat > 0 && curC.fat > 0) {
      uFat = (m.util || 0) * (Ac / An) * (curC.fat / c.fat);
    }
    return {uT,uC,uM,uStatic,uFat};
  }

  function isSafe(r, caps) {
    if (!r || r.error || !r.ok) return false;
    if (r.alphaCr != null && r.alphaCr < caps.alpha) return false;
    if (r.sag != null && r.sagLimit != null && r.sag > caps.sagFrac * r.sagLimit) return false;
    if (r.sway != null && r.swayLimit != null && r.sway > caps.swayFrac * r.swayLimit) return false;
    if (r.frequency != null && r.frequency < caps.freq) return false;
    if (r.fatigueWorst != null && r.fatigueWorst > caps.fatigueWorst) return false;
    if (r.robustness === false) return false;
    if (r.robustness && r.robustness.ok === false) return false;
    if (r.members) {
      for (let i=0;i<r.members.length;i++) {
        const m = r.members[i];
        if (!m) continue;
        const mode = (m.mode || "").toLowerCase();
        const cap = mode.includes("fatigue") ? caps.fat
                  : mode.includes("buckling") ? caps.buck
                  : caps.other;
        if ((m.util || 0) > cap + 1e-9) return false;
      }
    }
    return true;
  }

  function chooseSection(g, cur, r, caps) {
    let bestJ = -1, bestMass = Infinity;
    for (let j=0;j<cands.length;j++) {
      let ok = true;
      for (const k of g) {
        const m = r.members[k];
        if (!m) { ok = false; break; }
        const est = estimate(j, cur[k], m, topo[k].L);
        if (est.uT > caps.other + 1e-9 ||
            est.uC > caps.buck  + 1e-9 ||
            est.uM > caps.other + 1e-9 ||
            est.uStatic > caps.other + 1e-9 ||
            est.uFat > caps.fat + 1e-9) { ok = false; break; }
      }
      if (ok && cands[j].mass < bestMass - 1e-9) {
        bestMass = cands[j].mass;
        bestJ = j;
      }
    }
    if (bestJ >= 0) return bestJ;
    let bj = -1, bv = Infinity, bm = Infinity;
    for (let j=0;j<cands.length;j++) {
      let maxR = 0;
      for (const k of g) {
        const m = r.members[k];
        if (!m) continue;
        const est = estimate(j, cur[k], m, topo[k].L);
        const rr = Math.max(
          est.uT/caps.other, est.uC/caps.buck,
          est.uM/caps.other, est.uStatic/caps.other,
          est.uFat/caps.fat
        );
        if (rr > maxR) maxR = rr;
      }
      if (maxR < bv - 1e-9 || (Math.abs(maxR-bv) < 1e-9 && cands[j].mass < bm)) {
        bv = maxR; bj = j; bm = cands[j].mass;
      }
    }
    return bj;
  }

  function resize(startArr, caps, maxIter) {
    let cur = startArr.slice();
    let r = getReport(cur);
    let best = null, bestR = null, bestMass = Infinity;
    if (r && r.ok && isSafe(r,caps)) {
      best = cur.slice(); bestR = r; bestMass = r.mass;
    }
    for (let iter=0; iter<maxIter && calls<395; iter++) {
      if (!r || !r.ok || !r.members) break;
      let next = cur.slice();
      let changed = false;
      for (const g of groups) {
        if (calls >= 395) break;
        const curJ = cur[g[0]];
        const j = chooseSection(g, cur, r, caps);
        if (j >= 0 && j !== curJ) {
          for (const k of g) next[k] = j;
          changed = true;
        }
      }
      if (!changed) break;
      const nr = getReport(next);
      if (!nr || !nr.ok) break;
      cur = next; r = nr;
      if (isSafe(r,caps) && r.mass < bestMass - 1e-6) {
        best = cur.slice(); bestR = r; bestMass = r.mass;
      }
    }
    return best ? {arr:best, r:bestR, mass:bestMass} : null;
  }

  const strongIdx = findSpec("S690 CHS219.1x8");
  const strongArr = new Array(N).fill(strongIdx);

  const symSeed = new Array(N);
  for (const g of groups) {
    let bestJ = -1, bestMass = -1;
    for (const k of g) {
      let j = fallbackArr[k];
      const c = cands[j];
      const s690 = c.spec.replace(/^S(355|460) /, "S690 ");
      if (specMap.has(s690)) j = specMap.get(s690);
      const m = cands[j].mass;
      if (m > bestMass) { bestMass = m; bestJ = j; }
    }
    if (bestJ < 0) bestJ = strongIdx;
    for (const k of g) symSeed[k] = bestJ;
  }

  const fallbackS690Arr = fallbackArr.map(j=>{
    const s690 = cands[j].spec.replace(/^S(355|460) /, "S690 ");
    return specMap.has(s690) ? specMap.get(s690) : j;
  });

  function strengthen(seedArr, caps, maxIter) {
    let cur = seedArr.slice();
    let r = getReport(cur);
    if (!r || !r.ok) {
      cur = new Array(N).fill(strongIdx);
      r = getReport(cur);
    }
    for (let iter=0; iter<maxIter && calls<395; iter++) {
      if (!r || !r.ok) return null;
      if (isSafe(r,caps)) return {arr:cur.slice(), r, mass:r.mass};
      let next = cur.slice();
      let changed = false;
      for (const g of groups) {
        if (calls >= 395) break;
        let need = false;
        for (const k of g) {
          const m = r.members[k];
          if (!m) { need = true; break; }
          const mode = (m.mode || "").toLowerCase();
          const cap = mode.includes("fatigue") ? caps.fat
                    : mode.includes("buckling") ? caps.buck
                    : caps.other;
          if ((m.util || 0) > cap + 1e-9) { need = true; break; }
        }
        if (!need) continue;
        const curJ = cur[g[0]];
        let bestJ = -1, bestMass = Infinity;
        for (let j=0;j<cands.length;j++) {
          if (cands[j].mass < cands[curJ].mass - 1e-9) continue;
          let ok = true;
          for (const k of g) {
            const m = r.members[k];
            if (!m) { ok = false; break; }
            const est = estimate(j, cur[k], m, topo[k].L);
            if (est.uT > caps.other + 1e-9 ||
                est.uC > caps.buck  + 1e-9 ||
                est.uM > caps.other + 1e-9 ||
                est.uStatic > caps.other + 1e-9 ||
                est.uFat > caps.fat + 1e-9) { ok = false; break; }
          }
          if (ok && cands[j].mass < bestMass - 1e-9) {
            bestMass = cands[j].mass; bestJ = j;
          }
        }
        if (bestJ < 0) {
          let bj = curJ, bv = Infinity, bm = Infinity;
          for (let j=0;j<cands.length;j++) {
            if (cands[j].mass < cands[curJ].mass + 1e-9) continue;
            let maxR = 0;
            for (const k of g) {
              const m = r.members[k];
              if (!m) continue;
              const est = estimate(j, cur[k], m, topo[k].L);
              const rr = Math.max(
                est.uT/caps.other, est.uC/caps.buck,
                est.uM/caps.other, est.uStatic/caps.other,
                est.uFat/caps.fat
              );
              if (rr > maxR) maxR = rr;
            }
            if (maxR < bv - 1e-9 || (Math.abs(maxR-bv) < 1e-9 && cands[j].mass < bm)) {
              bv = maxR; bj = j; bm = cands[j].mass;
            }
          }
          bestJ = bj;
        }
        if (bestJ >= 0 && bestJ !== curJ) {
          for (const k of g) next[k] = bestJ;
          changed = true;
        }
      }
      if (!changed) {
        cur = new Array(N).fill(strongIdx);
        r = getReport(cur);
        if (r && r.ok && isSafe(r,caps)) return {arr:cur.slice(), r, mass:r.mass};
        return null;
      }
      const nr = getReport(next);
      if (!nr || !nr.ok) return null;
      cur = next; r = nr;
      if (isSafe(r,caps)) return {arr:cur.slice(), r, mass:r.mass};
    }
    return null;
  }

  function groupMass(g, arr) {
    let s = 0;
    for (const k of g) s += cands[arr[k]].mass * topo[k].L;
    return s;
  }
  function localDescent(startArr, caps, maxCalls) {
    let cur = startArr.slice();
    let r = getReport(cur);
    if (!r || !isSafe(r,caps)) return null;
    let best = {arr:cur.slice(), r, mass:r.mass};
    const limit = Math.min(395, calls + maxCalls);
    for (let pass=0; pass<3 && calls<limit; pass++) {
      let improved = false;
      const gs = groups.slice().sort((a,b)=>groupMass(b,cur)-groupMass(a,cur));
      for (const g of gs) {
        if (calls >= limit) break;
        const curJ = cur[g[0]];
        const opts = [];
        for (let j=0;j<cands.length;j++) {
          if (cands[j].mass >= cands[curJ].mass - 1e-9) continue;
          let ok = true;
          for (const k of g) {
            const m = r.members[k];
            if (!m) { ok = false; break; }
            const est = estimate(j, cur[k], m, topo[k].L);
            if (est.uT > caps.other*1.02 + 1e-9 ||
                est.uC > caps.buck*1.02 + 1e-9 ||
                est.uM > caps.other*1.02 + 1e-9 ||
                est.uStatic > caps.other*1.02 + 1e-9 ||
                est.uFat > caps.fat*1.02 + 1e-9) { ok = false; break; }
          }
          if (ok) opts.push(j);
        }
        opts.sort((a,b)=>cands[a].mass-cands[b].mass);
        let tried = 0;
        for (const j of opts) {
          if (calls >= limit) break;
          if (tried >= 3) break;
          const trial = cur.slice();
          for (const k of g) trial[k] = j;
          const tr = getReport(trial);
          tried++;
          if (tr && tr.ok && isSafe(tr,caps) && tr.mass < best.mass - 1e-6) {
            cur = trial; r = tr;
            best = {arr:trial.slice(), r:tr, mass:tr.mass};
            improved = true;
            break;
          }
        }
      }
      if (!improved) break;
    }
    return best;
  }

  const capsA = {fat:0.78, buck:0.72, other:0.82, alpha:9, sat:0, sagFrac:0.85, swayFrac:0.85, freq:2.25, fatigueWorst:0.78};
  const capsB = {fat:0.82, buck:0.78, other:0.86, alpha:8, sat:0, sagFrac:0.90, swayFrac:0.90, freq:2.15, fatigueWorst:0.82};

  let bestA = null, bestB = null, bestOK = null;
  function consider(res, level) {
    if (!res || !res.r || !res.r.ok) return;
    if (level === "A" && isSafe(res.r, capsA)) {
      if (!bestA || res.mass < bestA.mass) bestA = res;
    }
    if (level === "B" && isSafe(res.r, capsB)) {
      if (!bestB || res.mass < bestB.mass) bestB = res;
    }
    if (!bestOK || res.mass < bestOK.mass) bestOK = res;
  }

  const fb = getReport(fallbackArr);
  if (fb && fb.ok) consider({arr:fallbackArr, r:fb, mass:fb.mass}, "OK");
  const fbS = getReport(fallbackS690Arr);
  if (fbS && fbS.ok) consider({arr:fallbackS690Arr, r:fbS, mass:fbS.mass}, "OK");

  consider(resize(strongArr, capsA, 25), "A");
  consider(resize(symSeed,  capsA, 20), "A");
  consider(strengthen(symSeed, capsA, 15), "A");

  if (bestA && calls < 385) {
    const d = localDescent(bestA.arr, capsA, Math.min(110, 395-calls));
    if (d) consider(d, "A");
  }

  if (!bestA || bestA.mass > 16500) {
    consider(resize(strongArr, capsB, 20), "B");
    consider(resize(symSeed,  capsB, 20), "B");
    consider(strengthen(symSeed, capsB, 15), "B");
    if (bestB && calls < 385) {
      const d = localDescent(bestB.arr, capsB, Math.min(100, 395-calls));
      if (d) consider(d, "B");
    }
  }

  let finalRes = bestA || bestB || bestOK;
  if (!finalRes) {
    finalRes = fbS && fbS.ok
      ? {arr:fallbackS690Arr, r:fbS, mass:fbS.mass}
      : {arr:fallbackArr, r:fb, mass:fb ? fb.mass : 0};
  }

  const out = buildDesign(finalRes.arr);
  out.note = "Symmetric safety-graded triangular space truss; CHS/SHS only, strengthened against weakest-unit scatter and hidden load cases.";
  return out;
}

function design(site, analyse) {
  // Under-deck Warren truss: two lines at z = ±2.65 (depth 4.8 m), with deck-level and
  // bottom-level lateral bracing. Pinned joints throughout. Section sizes are set by
  // iterating analyse(): grow members with high utilisation, shrink lightly loaded ones,
  // grow the whole truss if a global check (sag, sway, frequency, alpha_cr) fails.
  const H = 4.8;
  const SIZES = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33], ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS168.3x5", 25.65], ["CHS139.7x6.3", 26.4], ["CHS168.3x6.3", 32.06], ["CHS193.7x6.3", 37.09],
    ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06], ["CHS244.5x8", 59.44], ["CHS273x10", 82.62],
    ["CHS323.9x10", 98.61]
  ];
  const MAXI = SIZES.length - 1;

  // Bottom nodes (Warren panel points), below deck
  const nodes = [];
  for (let k = 0; k < 10; k++) {
    const xm = +(4.03 * k + 2.015).toFixed(3);
    nodes.push({ id: "BL" + k, x: xm, y: -H, z: -2.65, joint: "pin" });
    nodes.push({ id: "BR" + k, x: xm, y: -H, z: 2.65, joint: "pin" });
  }

  // Member topology: [a, b, kind]
  const mem = [];
  const add = (a, b, kind) => mem.push([a, b, kind]);
  for (let i = 0; i < 10; i++) {
    add("L" + i, "L" + (i + 1), "chord");
    add("R" + i, "R" + (i + 1), "chord");
    add("L" + i, "BL" + i, "diag");
    add("BL" + i, "L" + (i + 1), "diag");
    add("R" + i, "BR" + i, "diag");
    add("BR" + i, "R" + (i + 1), "diag");
    add("BL" + i, "BR" + i, "brace");
  }
  for (let k = 0; k < 9; k++) {
    add("BL" + k, "BL" + (k + 1), "chord");
    add("BR" + k, "BR" + (k + 1), "chord");
    add("BL" + k, "BR" + (k + 1), "brace");
    add("BR" + k, "BL" + (k + 1), "brace");
  }
  for (let i = 0; i <= 10; i++) add("L" + i, "R" + i, "brace");      // deck cross girders (on y=0 face)
  for (let i = 0; i < 10; i++) {
    add("L" + i, "R" + (i + 1), "brace");                               // deck-plane lateral bracing
    add("R" + i, "L" + (i + 1), "brace");
  }

  const idx = mem.map(m => (m[2] === "chord" ? 14 : 10));

  const build = (ix, note) => ({
    note: note,
    nodes: nodes,
    joints: {},
    members: mem.map((m, i) => ({ a: m[0], b: m[1], spec: "S355 " + SIZES[ix[i]][0] }))
  });

  const NOTE = "Under-deck Warren truss pair at z=±2.65 (depth 4.8 m), pinned joints, deck-level and bottom lateral bracing; S355 CHS sized iteratively.";

  let best = null, bestMass = Infinity, last = null, calls = 0;

  for (let it = 0; it < 150 && calls < 330; it++) {
    const d = build(idx, NOTE);
    const res = analyse(d);
    calls++;
    if (!res || res.error) break;
    last = d;
    if (res.ok && typeof res.mass === "number" && res.mass < bestMass) {
      bestMass = res.mass;
      best = d;
    }

    const mrs = Array.isArray(res.members) ? res.members : [];
    const sagBad = typeof res.sag === "number" && typeof res.sagLimit === "number" && res.sag > res.sagLimit;
    const swayBad = typeof res.sway === "number" && typeof res.swayLimit === "number" && res.sway > res.swayLimit;
    const freqBad = typeof res.frequency === "number" && res.frequency < 2;
    const alphaBad = typeof res.alphaCr === "number" && res.alphaCr < 5;
    const globalBad = sagBad || swayBad || freqBad || alphaBad;

    let changed = false;
    if (globalBad) {
      for (let i = 0; i < mem.length; i++) {
        const u = mrs[i] && typeof mrs[i].util === "number" ? mrs[i].util : 0;
        if (u > 0.3 && idx[i] < MAXI) { idx[i]++; changed = true; }
      }
    } else {
      for (let i = 0; i < mem.length; i++) {
        const u = mrs[i] && typeof mrs[i].util === "number" ? mrs[i].util : 0;
        if (u > 0.95 && idx[i] < MAXI) { idx[i]++; changed = true; }
        else if (u < 0.5 && idx[i] > 0) { idx[i]--; changed = true; }
      }
    }
    if (!changed) break;
  }

  const fallback = build(idx, NOTE);
  const out = best || last || fallback;
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

function design(site, analyse) {
  // Triangular-section 3D truss (attempt 2). Deck chords L and R at z = ±2.65 (y = 0) with a
  // horizontal deck truss (cross members and one zig-zag diagonal per panel). A single bottom
  // apex chord runs at y = -4.9, z = 0 under every second deck node, with webs from each apex
  // to the three deck nodes above it on each side. The apex sits at z = 0, so every apex
  // member has a z component: this removes the z-sliding mechanism that broke attempt 1.
  // All joints pinned. Sizes are iterated with analyse().
  const NOTE = "Triangular-section 3D truss: deck chords with deck bracing, single bottom apex chord at y=-4.9, z=0 with webs to the deck nodes around each apex (no z-mechanism), all pinned, S355 CHS sized iteratively.";

  const SIZES = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2", "CHS60.3x4",
    "CHS76.1x3.2", "CHS76.1x4", "CHS88.9x4", "CHS88.9x5", "CHS114.3x4", "CHS114.3x5",
    "CHS139.7x5", "CHS168.3x5", "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x6.3",
    "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10", "CHS323.9x10",
    "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];
  const MAXI = SIZES.length - 1;

  // Apex nodes: A_k sits under deck node L_{2k+1}, at y = -4.9, z = 0
  const nodes = [];
  for (let k = 0; k < 5; k++) {
    nodes.push({ id: "A" + k, x: +(4.03 + 8.06 * k).toFixed(3), y: -4.9, z: 0, joint: "pin" });
  }

  const mem = [];
  const add = (a, b, kind) => mem.push({ a: a, b: b, kind: kind });

  // Deck chords
  for (let i = 0; i < 10; i++) {
    add("L" + i, "L" + (i + 1), "top");
    add("R" + i, "R" + (i + 1), "top");
  }
  // Deck cross members
  for (let i = 0; i <= 10; i++) add("L" + i, "R" + i, "deck");
  // Deck zig-zag diagonals (one per panel)
  for (let i = 0; i < 10; i++) {
    if (i % 2 === 0) add("L" + i, "R" + (i + 1), "deck");
    else add("R" + i, "L" + (i + 1), "deck");
  }
  // Bottom apex chord
  for (let k = 0; k < 4; k++) add("A" + k, "A" + (k + 1), "apex");
  // Webs and verticals to each side
  for (let k = 0; k < 5; k++) {
    for (const s of ["L", "R"]) {
      add("A" + k, s + (2 * k), "web");
      add("A" + k, s + (2 * k + 2), "web");
      add("A" + k, s + (2 * k + 1), "vert");
    }
  }

  const START = { top: 14, deck: 7, apex: 17, web: 12, vert: 9 };
  let idx = mem.map(m => START[m.kind]);

  const build = () => ({
    note: NOTE,
    nodes: nodes,
    joints: {},
    members: mem.map((m, i) => ({ a: m.a, b: m.b, spec: "S355 " + SIZES[idx[i]] }))
  });

  let best = null, bestMass = Infinity, last = null, calls = 0;

  for (let it = 0; it < 150 && calls < 300; it++) {
    const d = build();
    const res = analyse(d);
    calls++;
    if (!res || res.error) break;
    last = d;

    const fail = String(res.failure || "");
    if (/mechanism/i.test(fail)) break;

    if (res.ok && typeof res.mass === "number" && res.mass < bestMass) {
      bestMass = res.mass;
      best = d;
    }

    const mrs = Array.isArray(res.members) ? res.members : [];
    const near = (v, l) => typeof v === "number" && typeof l === "number" && v > 0.92 * l;
    const sagBad = near(res.sag, res.sagLimit);
    const swayBad = near(res.sway, res.swayLimit);
    const freqBad = typeof res.frequency === "number" && res.frequency < 2.2;
    const alphaBad = typeof res.alphaCr === "number" && res.alphaCr < 8;
    const glob = sagBad || swayBad || freqBad || alphaBad;

    let changed = false;
    for (let i = 0; i < mem.length; i++) {
      const u = mrs[i] && typeof mrs[i].util === "number" ? mrs[i].util : 0;
      if (u > 0.9 || (glob && u > 0.4)) {
        if (idx[i] < MAXI) { idx[i]++; changed = true; }
      } else if (!glob && u < 0.45 && idx[i] > 0) {
        idx[i]--; changed = true;
      }
    }
    if (!changed) break;
  }

  const out = best || last || build();
  return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
}

function design(site, analyse) {
  // Warren-prism 3D truss. q=1: deck nodes every 4.03 m (attempt-2 layout). q=2: extra unloaded
  // top nodes at 2.015 m so top compression chords have short buckling lengths. Apex (bottom)
  // nodes at y=-4.9, z=0 sit at odd grid positions. All joints pinned. Sizes are iterated with
  // analyse(): grow members with utilisation above 0.92, shrink those below 0.45, and grow
  // the members with utilisation above 0.5 when a global check (sag, sway, frequency, alpha_cr)
  // is close to failing. The lightest passing design over both layouts is returned.
  const SZ = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94], ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33], ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86], ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS168.3x5", 25.65], ["CHS139.7x6.3", 26.4], ["CHS168.3x6.3", 32.06], ["CHS193.7x6.3", 37.09],
    ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06], ["CHS244.5x8", 59.44], ["CHS273x10", 82.62],
    ["CHS323.9x10", 98.61], ["CHS355.6x12.5", 134.74], ["CHS406.4x12.5", 154.68], ["CHS457x16", 221.67]
  ];
  const MAXI = SZ.length - 1;
  const t0 = Date.now();
  const H = 4.9;
  const firstAtLeast = a => {
    for (let i = 0; i <= MAXI; i++) if (SZ[i][1] >= a) return i;
    return MAXI;
  };
  const NOTE = "Warren-prism 3D truss (triangular section, apexes at y=-4.9, z=0), top nodes at 2.015 m with unloaded mid nodes to shorten compression chords, all pinned, S355 CHS sized by iterated analyse().";

  function run(q, budget, START, maxIt) {
    const s = 4.03 / q;
    const NP = 10 * q;
    const tl = j => (j % q === 0 ? "L" + (j / q) : "ML" + j);
    const tr = j => (j % q === 0 ? "R" + (j / q) : "MR" + j);

    const nodes = [];
    for (let j = 0; j <= NP; j++) {
      if (j % q !== 0) {
        const x = +(s * j).toFixed(3);
        nodes.push({ id: tl(j), x: x, y: 0, z: -2.65, joint: "pin" });
        nodes.push({ id: tr(j), x: x, y: 0, z: 2.65, joint: "pin" });
      }
    }
    for (let j = 1; j < NP; j += 2) {
      nodes.push({ id: "A" + j, x: +(s * j).toFixed(3), y: -H, z: 0, joint: "pin" });
    }

    const mem = [];
    const add = (a, b, kind) => mem.push({ a: a, b: b, kind: kind });
    for (let j = 0; j < NP; j++) {
      add(tl(j), tl(j + 1), "top");
      add(tr(j), tr(j + 1), "top");
    }
    for (let j = 0; j <= NP; j++) add(tl(j), tr(j), "cross");
    for (let j = 0; j < NP; j++) {
      if (j % 2 === 0) add(tl(j), tr(j + 1), "zig");
      else add(tr(j), tl(j + 1), "zig");
    }
    for (let j = 1; j + 2 <= NP - 1; j += 2) add("A" + j, "A" + (j + 2), "apexch");
    for (let j = 1; j < NP; j += 2) {
      const a = "A" + j;
      add(a, tl(j - 1), "web");
      add(a, tl(j + 1), "web");
      add(a, tr(j - 1), "web");
      add(a, tr(j + 1), "web");
      add(a, tl(j), "vert");
      add(a, tr(j), "vert");
    }

    const idx = mem.map(m => START[m.kind]);
    const build = () => ({
      note: NOTE,
      nodes: nodes,
      joints: {},
      members: mem.map((m, i) => ({ a: m.a, b: m.b, spec: "S355 " + SZ[idx[i]][0] }))
    });

    let best = null, bestMass = Infinity, last = null, calls = 0;
    for (let it = 0; it < maxIt && calls < budget; it++) {
      if (Date.now() - t0 > 65000) break;
      const d = build();
      const res = analyse(d);
      calls++;
      if (!res || res.error) break;
      last = d;
      if (/mechanism/i.test(String(res.failure || ""))) break;
      if (res.ok && typeof res.mass === "number" && res.mass < bestMass) {
        bestMass = res.mass;
        best = d;
      }
      const mrs = Array.isArray(res.members) ? res.members : [];
      const near = (v, l) => typeof v === "number" && typeof l === "number" && v > 0.95 * l;
      const glob = near(res.sag, res.sagLimit) || near(res.sway, res.swayLimit) ||
        (typeof res.frequency === "number" && res.frequency < 2.1) ||
        (typeof res.alphaCr === "number" && res.alphaCr < 5.5);

      let changed = false;
      for (let i = 0; i < mem.length; i++) {
        const u = mrs[i] && typeof mrs[i].util === "number" ? mrs[i].util : 0;
        const k = idx[i];
        let nk = k;
        if (u > 0.92 || (glob && u > 0.5)) {
          nk = Math.max(firstAtLeast(SZ[k][1] * Math.max(u, 0.6) / 0.85), k + 1);
        } else if (!glob && u < 0.45 && k > 0) {
          nk = Math.min(firstAtLeast(SZ[k][1] * u / 0.75), k - 1);
        }
        nk = Math.max(0, Math.min(MAXI, nk));
        if (nk !== k) {
          idx[i] = nk;
          changed = true;
        }
      }
      if (!changed) break;
    }
    return { best: best, bestMass: bestMass, last: last };
  }

  const START_Q2 = { top: 14, cross: 9, zig: 9, apexch: 16, web: 13, vert: 10 };
  const START_Q1 = { top: 16, cross: 8, zig: 9, apexch: 18, web: 13, vert: 10 };

  const r2 = run(2, 200, START_Q2, 200);
  const r1 = run(1, 150, START_Q1, 150);

  const cands = [r1, r2].filter(r => r.best);
  if (cands.length) {
    cands.sort((a, b) => a.bestMass - b.bestMass);
    const out = cands[0].best;
    return { note: out.note, nodes: out.nodes, joints: out.joints, members: out.members };
  }
  const fb = r2.last || r1.last;
  return { note: NOTE, nodes: fb.nodes, joints: fb.joints, members: fb.members };
}

