  const TOPO = "L0 L1 CHS219.1x8;R0 R1 CHS273x10;L1 L2 CHS219.1x8;R1 R2 CHS139.7x5;L2 L3 CHS193.7x8;R2 R3 CHS193.7x6.3;L3 L4 CHS193.7x8;R3 R4 CHS193.7x8;L4 L5 CHS244.5x8;R4 R5 CHS193.7x8;L5 L6 CHS244.5x8;R5 R6 CHS219.1x8;L6 L7 CHS219.1x8;R6 R7 CHS273x10;L7 L8 CHS219.1x8;R7 R8 CHS219.1x8;L8 L9 CHS168.3x5;R8 R9 CHS193.7x8;L9 L10 CHS168.3x5;R9 R10 CHS168.3x5;L0 R0 CHS168.3x5;L1 R1 CHS42.4x3.2;L2 R2 CHS76.1x3.2;L3 R3 CHS88.9x4;L4 R4 CHS60.3x3.2;L5 R5 CHS88.9x4;L6 R6 CHS60.3x3.2;L7 R7 CHS88.9x4;L8 R8 CHS76.1x3.2;L9 R9 CHS42.4x3.2;L10 R10 CHS168.3x5;L0 R1 CHS273x10;R1 L2 CHS193.7x8;L2 R3 CHS193.7x6.3;R3 L4 CHS168.3x5;L4 R5 CHS114.3x5;R5 L6 CHS114.3x5;L6 R7 CHS88.9x4;R7 L8 CHS168.3x5;L8 R9 CHS168.3x6.3;R9 L10 CHS193.7x6.3;A1 A3 CHS193.7x8;A3 A5 CHS244.5x8;A5 A7 CHS244.5x8;A7 A9 CHS193.7x8;A1 L0 CHS168.3x6.3;A1 L2 CHS193.7x8;A1 R0 CHS139.7x5;A1 R2 CHS244.5x8;A1 L1 CHS139.7x5;A1 R1 CHS139.7x5;A3 L2 CHS139.7x5;A3 L4 CHS168.3x6.3;A3 R2 CHS139.7x5;A3 R4 CHS193.7x6.3;A3 L3 CHS139.7x5;A3 R3 CHS139.7x5;A5 L4 CHS139.7x6.3;A5 L6 CHS168.3x5;A5 R4 CHS114.3x5;A5 R6 CHS114.3x4;A5 L5 CHS139.7x5;A5 R5 CHS139.7x5;A7 L6 CHS193.7x6.3;A7 L8 CHS168.3x5;A7 R6 CHS168.3x5;A7 R8 CHS88.9x5;A7 L7 CHS168.3x5;A7 R7 CHS139.7x5;A9 L8 CHS219.1x8;A9 L10 CHS168.3x6.3;A9 R8 CHS193.7x8;A9 R10 CHS114.3x5;A9 L9 CHS139.7x5;A9 R9 CHS139.7x5";

  const mem0 = TOPO.split(";").map(s => {
    const p = s.trim().split(" ");
    return { a: p[0], b: p[1], sz: SZ.findIndex(e => e[0] === p[2]), alive: true };
  });

  const build = st => {
    const members = [], map = [];
    st.forEach((m, i) => {
      if (m.alive) { members.push({ a: m.a, b: m.b, spec: "S690 " + SZ[m.sz][0] }); map.push(i); }
    });
    return { d: { note: NOTE, nodes: NODES, joints: {}, members: members }, map: map };
  };
  const fallback = build(mem0).d;

  let calls = 0;
  const timeUp = () => (Date.now() - t0 > TLIM) || calls >= BUDGET;
  const lim = (v, L, f) => (typeof v !== "number" || typeof L !== "number") ? true : v <= f * L;

  function evalState(st) {
    if (timeUp()) return null;
    const b = build(st);
    let res = null;
    try { res = analyse(b.d); } catch (e) { res = null; }
    calls++;
    if (!res || res.error || typeof res.mass !== "number") return { good: false };
    const mrs = Array.isArray(res.members) ? res.members : [];
    if (mrs.length !== b.map.length) return { good: false };
    const utils = mrs.map(r => (r && typeof r.util === "number") ? r.util : 1);
    const modes = mrs.map(r => String((r && r.mode) || ""));
    let good = !!res.ok &&
      (typeof res.maxUtil !== "number" || res.maxUtil <= 0.80) &&
      (typeof res.fatigueWorst !== "number" || res.fatigueWorst <= 0.85) &&
      (typeof res.frequency !== "number" || res.frequency >= 2.2) &&
      (typeof res.alphaCr !== "number" || res.alphaCr >= 6) &&
      lim(res.sag, res.sagLimit, 0.85) && lim(res.sway, res.swayLimit, 0.85);
    if (good) {
      for (let k = 0; k < utils.length; k++) {
        const fat = /fatigue/i.test(modes[k]);
        if (utils[k] > (fat ? 0.85 : 0.80)) { good = false; break; }
      }
    }
    return { good: good, mass: res.mass, map: b.map, utils: utils, modes: modes };
  }

  let st = mem0.map(m => Object.assign({}, m));
  let cur = evalState(st);
  if (!cur || !cur.good) return fallback;

  const utilOf = new Array(st.length).fill(0);
  const modeOf = new Array(st.length).fill("");
  const absorb = ev => ev.map.forEach((si, k) => { utilOf[si] = ev.utils[k]; modeOf[si] = ev.modes[k]; });
  absorb(cur);

  const smaller = sz => {
    const A = SZ[sz][1];
    let j = -1;
    for (let q = 0; q < SZ.length; q++) if (SZ[q][1] < A - 1e-9) j = q;
    return j;
  };

  const mutRemove = (t, i) => {
    if (!t[i].alive) return false;
    t[i].alive = false;
    return true;
  };
  const mutShrink = (t, i) => {
    if (!t[i].alive) return false;
    const j = smaller(t[i].sz);
    if (j < 0) return false;
    const pred = utilOf[i] * SZ[t[i].sz][1] / SZ[j][1];
    const fat = /fatigue/i.test(modeOf[i]);
    if (pred > (fat ? 0.85 : 0.80)) return false;
    t[i].sz = j;
    return true;
  };

  function sweep(cands, mutate) {
    let improved = false;
    let pos = 0, chunk = cands.length;
    while (pos < cands.length && !timeUp()) {
      const grp = cands.slice(pos, pos + chunk);
      const trial = st.map(m => Object.assign({}, m));
      let changed = false;
      for (const i of grp) if (mutate(trial, i)) changed = true;
      if (!changed) { pos += grp.length; continue; }
      const ev = evalState(trial);
      if (ev && ev.good && ev.mass < cur.mass - 1e-6) {
        st = trial;
        cur = ev;
        absorb(ev);
        improved = true;
        pos += grp.length;
        chunk = Math.min(cands.length, Math.max(1, chunk * 2));
      } else if (grp.length > 1) {
        chunk = Math.max(1, grp.length >> 1);
      } else {
        pos += 1;
      }
    }
    return improved;
  }

  for (let round = 0; round < 6 && !timeUp(); round++) {
    let any = false;

    const rc = [];
    st.forEach((m, i) => { if (m.alive && utilOf[i] < 0.30) rc.push(i); });
    rc.sort((p, q) => utilOf[p] - utilOf[q]);
    if (rc.length && sweep(rc, mutRemove)) any = true;

    const sc = [];
    st.forEach((m, i) => { if (m.alive && utilOf[i] < 0.80) sc.push(i); });
    sc.sort((p, q) => SZ[st[q].sz][1] - SZ[st[p].sz][1]);
    if (sc.length && sweep(sc, mutShrink)) any = true;

    if (!any) break;
  }

  return build(st).d;
}
